/* -- The one renderer for a create action that used to be a sidebar row. Returns '' when this
   role or persona may not perform it, so a listing every persona can read does not hand every
   persona the button. Super Admin is excluded everywhere: it configures what an object is
   (Data Foundation), it does not fill one in — the same rule the old nav rows carried. -- */
function pageActionBtn(id,label,call){
  if(typeof canUsePageAction!=='function'||!canUsePageAction(id,['entity-admin','entity-user']))return '';
  return '<button class="lp-pill-action" onclick="'+call+'" title="'+attrSafe(label)+'">'
    +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" width="13" height="13"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>'
    +'<span>'+label+'</span></button>';
}
// -- DASHBOARD: tab bar + per-role tab dispatch --
function buildDashboardTabsHTML(){
  const tabs=dashboardTabsForRole(portalRole);
  if(tabs.length<2)return '';
  if(!tabs.some(t=>t.id===dashboardTab))dashboardTab=tabs[0]?tabs[0].id:'employee';
  return '<div class="dash-tabs">'+tabs.map(function(t){
    return '<button class="dash-tab'+(dashboardTab===t.id?' active':'')+'" onclick="switchDashboardTab(\''+t.id+'\')">'+t.label+'</button>';
  }).join('')+'</div>';
}
function buildDashboardPageHTML(){
  const tabs=dashboardTabsForRole(portalRole);
  if(!tabs.some(t=>t.id===dashboardTab))dashboardTab=tabs[0]?tabs[0].id:'employee';
  const body=dashboardTab==='employee'?buildEmployeeDashboardHTML()
    :dashboardTab==='entity-admin'?buildEntityAdminDashboardHTML()
    :portalRole==='entity-user'?buildPersonaRoleDashboardHTML(dashboardTab)
    :dashboardContentHTML;
  return buildDashboardTabsHTML()+body;
}

function dashStat(label,val,sub,kind){
  const color=kind==='green'?'#16a34a':kind==='red'?'#dc2626':kind==='orange'?'var(--orange)':'var(--navy)';
  return '<div class="stat-card"><div class="stat-label"><span>'+label+'</span></div><div class="stat-val" style="color:'+color+'">'+val+'</div><div class="stat-sub">'+(sub||'')+'</div></div>';
}
// -- Interactive stat card: same hero-tile treatment as Super Admin/Entity Admin dashboards. pageId is optional — omit it when no matching page exists yet, and the card renders without a click action. customClick (raw JS, e.g. to pre-set a filter before navigating) overrides the plain navigatePage(pageId) call when given. --
function dashStatNav(label,val,sub,kind,icon,pageId,customClick,flatVal){
  const colorClass=kind==='green'?'cfg-hero-green':kind==='red'?'cfg-hero-red':kind==='orange'?'cfg-hero-orange':kind==='teal'?'cfg-hero-teal':kind==='violet'?'cfg-hero-violet':'cfg-hero-blue';
  const valColor=flatVal?'var(--navy)':kind==='green'?'#16a34a':kind==='red'?'#dc2626':kind==='orange'?'var(--orange)':kind==='teal'?'#0d9488':kind==='violet'?'#7c3aed':'var(--navy)';
  const click=customClick?' onclick="'+customClick+'"':pageId?' onclick="navigatePage(\''+pageId+'\')"':'';
  const staticClass=(pageId||customClick)?'':' dash-stat-static';
  return '<div class="stat-card ea-hero-stat '+colorClass+staticClass+'"'+click+'><div class="stat-label"><span>'+label+'</span><div class="stat-icon">'+icon+'</div></div><div class="stat-val" style="color:'+valColor+'">'+val+'</div><div class="stat-sub">'+(sub||'')+'</div></div>';
}
function dashAction(title,sub,icon){
  return '<div class="dash-action-card"><div class="dash-action-icon">'+(icon||'')+'</div><div><div class="dash-action-title">'+title+'</div><div class="dash-action-sub">'+sub+'</div></div></div>';
}
function dashTable(title,columns,rows,link){
  return '<div class="listing-card dash-panel"><div class="dash-panel-head"><div>'+title+'</div>'+(link?'<span>'+link+'</span>':'')+'</div><table class="listing-table dash-table"><thead><tr>'+columns.map(function(c){return '<th>'+c+'</th>';}).join('')+'</tr></thead><tbody>'+rows.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+c+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div>';
}
function statusMini(text,type){return '<span class="dash-status '+(type||'pending')+'">'+text+'</span>';}
const dashIcoDoc='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>';
const dashIcoUser='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
const dashIcoMoney='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>';
const dashIcoShield='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>';
const dashIcoCalendar='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
const dashIcoAlert='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';
function buildPersonaRoleDashboardHTML(tab){
  const p=getActivePersona();
  // The Sub-Contracting journey board — step tiles plus this actor's work (js/subcontracting.js).
  if(tab==='sc-journeys')return buildScDashboardHTML();
  if(tab==='hr')return buildHRDashboardHTML();
  if(tab==='manager')return buildReportingManagerDashboardHTML(p);
  if(tab==='finance-approval'||tab==='finance-admin')return buildFinanceApprovalDashboardHTML();
  if(tab==='compliance')return buildComplianceDashboardHTML();
  if(tab==='store-ops')return buildStoreOpsDashboardHTML();
  if(tab==='ops')return buildOpsDashboardHTML();
  if(tab==='ops-approvals')return buildOpsApprovalsDashboardHTML();
  if(tab==='sales'||tab==='sales-approvals')return buildSalesDashboardHTML(p,tab);
  if(tab==='sales-team')return buildSalesTeamDashboardHTML();
  if(tab==='contracts-admin')return buildContractsAdminDashboardHTML();
  if(tab==='it-admin')return buildITAdminDashboardHTML();
  return buildPersonaDashboardHTML();
}
function dashHeader(title,sub){
  return '<div class="dash-ref"><div class="dash-ref-title">'+title+'</div><div class="dash-ref-sub">'+sub+'</div>';
}

// -- MANUAL MODE: live run cards reused on persona dashboards and My Tasks --
function manualRunCardHTML(r,opts){
  opts=opts||{};
  const c=cockpitRunComputed(r);
  const slaClass=r.slaRisk==='High'?'inactive':r.slaRisk==='Medium'?'unapproved':'active';
  const slaPriorityLabel={High:'High Priority',Medium:'Medium Priority',Low:'Low Priority'};
  const progressBar='<div class="cockpit-progress"><span style="width:'+c.progress+'%"></span></div><div class="cockpit-progress-meta"><span>'+c.progress+'% complete</span><span>'+(c.st.name||'Current step')+'</span></div>';
  const actionBtn=opts.actionBtn?opts.actionBtn(r):'';
  const cardClick=opts.cardClick?opts.cardClick(r):("openManualRunPreviewModal('"+r.runId+"')");
  return '<div class="cockpit-run-card" onclick="'+cardClick+'">'
    +'<div class="cockpit-run-head"><div class="cockpit-run-head-main"><div class="cockpit-run-id">'+r.runId+'</div><div class="cockpit-run-entity">'+(r.entity||'Dhi Hyperlocal')+'</div></div><span class="status-pill '+slaClass+'">'+(slaPriorityLabel[r.slaRisk]||r.slaRisk)+'</span></div>'
    +progressBar
    +'<div class="cockpit-run-mini-sub"><span>'+(r.subject||c.j.name||r.journeyId)+'</span>'+actionBtn+'</div>'
    +'</div>';
}
function manualRunListPanelHTML(title,runs,emptyText,opts){
  opts=opts||{};
  const body=runs.length
    ?'<div class="cockpit-run-list">'+runs.map(function(r){return manualRunCardHTML(r,opts);}).join('')+'</div>'
    :'<div class="cockpit-empty-state">'+emptyText+'</div>';
  return '<div class="listing-card dash-panel'+(opts.bare?' cockpit-run-panel':'')+'"><div class="dash-panel-head"><div>'+title+'</div></div>'+body+'</div>';
}
function buildMyCreatedRunsPanelHTML(personaId){
  const runs=manualJourneyRuns.filter(function(r){return r.journeyId==='contract-creation'&&r.createdBy===personaId;});
  // -- Jump straight into the ongoing journey run, not the preview modal — this is "my open deals," so one click should land on the live journey. --
  const cardClick=function(r){return "selectedManualRunId='"+r.runId+"';manualJourneyBackPage=page||'ai-executive';page='manual-journey-run';renderADTPage();";};
  return manualRunListPanelHTML('Open Deals',runs,'No open deals yet — create a contract to start one.',{cardClick:cardClick,bare:true});
}
/* == MY RUNS ============================================================================
   Every journey run the current user started, whatever its status.

   This is the surface that did not exist. Every other run list filters by *pending action* —
   aiAllPendingRuns keeps only Waiting/Exception, myPendingManualRuns keeps only runs whose
   CURRENT step this persona owns and drops anything Completed. So a run you started vanished
   from your view the moment it advanced to someone else's step, and permanently once it
   finished. This one filters by who started it, so it never disappears.

   The two stores hold different shapes — manual runs carry subject/entity/slaRisk, AI runs
   carry client/country/contractType — so both are normalised to one row here rather than
   forcing the renderer to know which store a row came from. == */
function myStartedRuns(){
  const me=currentActorId();
  const out=[];
  manualJourneyRuns.forEach(function(r){
    if(runStartedBy(r)!==me)return;
    const j=aiJourneys.find(function(x){return x.id===r.journeyId;})||cfgJourneys.find(function(x){return x.id===r.journeyId;});
    const st=manualJourneySteps(r.journeyId)[r.currentStepIdx]||{};
    out.push({
      kind:'manual',runId:r.runId,journeyId:r.journeyId,
      journeyName:j?j.name:r.journeyId,
      subject:r.subject||'—',
      meta:r.entity||'',
      mode:r.mode||'Manual',
      status:r.status,
      stepName:st.name||'—',
      stepOwner:st.ownerRole||'—',
      when:r.startedAt||'—'
    });
  });
  Object.keys(aiAutomationRuns).forEach(function(jid){
    const j=aiJourneys.find(function(x){return x.id===jid;});
    const events=aiJourneyEvents[jid]||[];
    (aiAutomationRuns[jid]||[]).forEach(function(r){
      if(runStartedBy(r)!==me)return;
      const ev=events[Math.min(r.currentStepIdx||0,Math.max(events.length-1,0))]||{};
      out.push({
        kind:'ai',runId:r.runId,journeyId:jid,
        journeyName:j?j.name:jid,
        subject:r.client||'—',
        meta:(r.country||'')+(r.contractType?' · '+r.contractType:''),
        // AI runs carry no mode field — being in this store is what makes them agent runs.
        mode:'Agent Enabled',
        status:r.status,
        stepName:ev.name||'—',
        stepOwner:ev.source||'—',
        when:r.lastActivity||r.startedAt||'—'
      });
    });
  });
  // -- Anything still moving comes first: a finished run is a record, an open one may need you. --
  const done={Completed:1};
  out.sort(function(a,b){return (done[a.status]?1:0)-(done[b.status]?1:0);});
  return out;
}
// -- The two stores also need different doors: a manual run opens its live journey page, an AI
// run opens Run Detail, which reads selectedAIJourneyId rather than taking it as an argument. --
function openMyRun(kind,journeyId,runId){
  if(kind==='manual'){
    selectedManualRunId=runId;
    manualJourneyBackPage=page||'ai-executive';
    page='manual-journey-run';
    renderADTPage();
    return;
  }
  selectedAIJourneyId=journeyId;
  viewAIRun(runId);
}
/* -- Continuing a run and inspecting one are different intents, and View Run only served the
   second: it drops you on the run page, from which the actual work is still one more hop away.
   So each row carries a state-driven primary CTA alongside it. Per-row rather than one "resume
   last run" banner above the table, because eligibility is per-row — a run parked on another
   role is not mine to continue, and a CTA that lands you somewhere you can act on nothing is
   worse than no CTA. Null here means the row keeps View Run alone. -- */
function mrRunAction(r){
  if(r.status==='Completed')return null;
  if(r.kind==='manual'){
    const run=getManualRun(r.runId);if(!run)return null;
    const cur=manualJourneySteps(run.journeyId)[run.currentStepIdx];
    const mine=portalRole!=='entity-user'||activePersonaId===manualStepOwnerPersonaId(cur&&cur.ownerRole);
    if(!mine)return null;
    return (run.exceptions||[]).some(function(e){return e.status==='Open';})
      ?{label:'Resolve Blocker'}:{label:'Continue'};
  }
  // -- An agent run only has a human door open at these two states; mid-automation there is
  // genuinely nothing to continue, which the My Tasks panel says in words too. --
  if(r.status==='Exception')return{label:'Resolve Blocker'};
  if(r.status==='Waiting for Approval')return{label:'Review &amp; Approve'};
  return null;
}
// -- Deliberately not openMyRun: Continue skips the run page and lands on the surface the step is
// actually done on (Contracts tab, Compliance Hub, Direct, Payroll), which is what openMyManualTask
// already resolves for the My Tasks queue. A blocked run is the exception — its resolver lives in
// the run page's Exceptions panel, so that one goes through the front door. --
function continueMyRun(kind,journeyId,runId){
  if(kind==='manual'){
    const run=getManualRun(runId);
    if(run&&(run.exceptions||[]).some(function(e){return e.status==='Open';})){openMyRun('manual',journeyId,runId);return;}
    openMyManualTask(runId,page||'my-runs');
    return;
  }
  // -- The agent action panel is anchored to #mt-task-sb, which only exists on My Tasks, so the
  // page has to be on screen before the panel can open — same order mtTaskRefresh uses. --
  selectedAIJourneyId=journeyId;
  navigatePage('my-tasks');
  openMyTaskAction(runId,journeyId);
}
function myRunStatusClass(s){
  if(s==='Completed')return 'active';
  if(s==='Exception'||s==='Blocked')return 'inactive';
  if(s==='Waiting for Approval'||s==='Waiting Approval')return 'pending';
  return 'draft';
}
/* -- The two stores name the same situations differently — manual runs say Blocked and Waiting
   Approval, AI runs say Exception and Waiting for Approval. Four groups collapse that so the
   status tiles count one thing each; the table keeps the raw status, because "Blocked" and
   "Exception" do mean different things once you are looking at the run itself. -- */
function mrStatusGroup(s){
  if(s==='Completed')return 'Completed';
  if(s==='Exception'||s==='Blocked')return 'Needs Attention';
  if(s==='Waiting for Approval'||s==='Waiting Approval')return 'Waiting Approval';
  return 'In Progress';
}
const mrAnyOption={journey:'All Journeys',mode:'All Modes'};
function setMrFilter(kind,val){
  const v=val===mrAnyOption[kind]?'':val;
  if(kind==='journey')mrJourneyFilter=v;else mrModeFilter=v;
  renderADTPage();
}
function setMrStatusFilter(val){mrStatusFilter=val||'';renderADTPage();}
function resetMrFilters(){mrJourneyFilter='';mrModeFilter='';mrStatusFilter='';mrSearchQuery='';renderADTPage();}
function applyMrSearch(){
  const el=document.getElementById('mr-search-input');
  mrSearchQuery=el?el.value.trim():'';
  renderADTPage();
}
function mrHasActiveFilters(){return !!(mrJourneyFilter||mrModeFilter||mrStatusFilter||mrSearchQuery);}
// -- Everything except status, so the tiles count against the current slice rather than the whole
// history — a tile reading 3 that yields nothing when clicked is worse than no tile. --
function mrRowsBeforeStatus(all){
  const q=mrSearchQuery.toLowerCase();
  return all.filter(function(r){
    if(mrJourneyFilter&&r.journeyName!==mrJourneyFilter)return false;
    if(mrModeFilter&&r.mode!==mrModeFilter)return false;
    if(!q)return true;
    return [r.runId,r.subject,r.journeyName,r.stepName,r.stepOwner].some(function(f){
      return f&&String(f).toLowerCase().indexOf(q)!==-1;
    });
  });
}
function mrDistinct(all,pick){
  const seen=[];
  all.forEach(function(r){const v=pick(r);if(v&&seen.indexOf(v)===-1)seen.push(v);});
  return seen.sort();
}
function buildMyRunsPageHTML(){
  const all=myStartedRuns();
  const base=mrRowsBeforeStatus(all);
  const rows=base.filter(function(r){return !mrStatusFilter||mrStatusGroup(r.status)===mrStatusFilter;});
  const counts={'In Progress':0,'Waiting Approval':0,'Needs Attention':0,Completed:0};
  base.forEach(function(r){counts[mrStatusGroup(r.status)]++;});

  const statTile=function(label,count,color){
    const on=mrStatusFilter===label;
    return '<div class="listing-stat'+(on?' stat-selected':'')+'" onclick="setMrStatusFilter(\''+(on?'':label)+'\')" title="'+(on?'Show all runs':'Show only '+label.toLowerCase()+' runs')+'">'
      +'<div class="listing-stat-count" style="color:'+color+'">'+count+'</div>'
      +'<div class="listing-stat-label">'+label+'</div>'
      +'</div>';
  };
  const tableRows=rows.length?rows.map(function(r,i){
    const open="openMyRun('"+r.kind+"','"+r.journeyId+"','"+r.runId+"')";
    return '<tr style="cursor:pointer" onclick="'+open+'">'
      +'<td style="color:var(--gray);font-size:13px">'+(i+1)+'</td>'
      +'<td style="font-family:monospace;font-size:12px;font-weight:600;color:var(--navy)">'+r.runId+'</td>'
      +'<td><div class="cell-primary">'+r.journeyName+'</div><div class="cell-sub">'+r.mode+'</div></td>'
      +'<td><div class="cell-primary">'+r.subject+'</div><div class="cell-sub">'+(r.meta||'')+'</div></td>'
      // -- Step plus its owner, so a run parked on someone else reads as "waiting on them",
      // not as something the user forgot to do. --
      +'<td><div class="cell-primary">'+r.stepName+'</div><div class="cell-sub">'+r.stepOwner+'</div></td>'
      +'<td><span class="status-pill '+myRunStatusClass(r.status)+'">'+r.status+'</span></td>'
      +'<td class="cell-sub">'+r.when+'</td>'
      +'<td onclick="event.stopPropagation()"><div class="mr-row-actions">'
      +(function(){const a=mrRunAction(r);return a?'<button class="btn btn-primary btn-sm" onclick="continueMyRun(\''+r.kind+'\',\''+r.journeyId+'\',\''+r.runId+'\')">'+a.label+'</button>':'';})()
      +'<button class="btn btn-secondary btn-sm" onclick="'+open+'">View Run</button></div></td>'
      +'</tr>';
  }).join('')
  // -- Filtered-to-nothing must not look like never-started-anything: one sends you to Reset,
  // the other tells you the feature is waiting on you to use it. --
  :'<tr><td colspan="8" style="padding:44px 16px;text-align:center">'
    +(all.length&&mrHasActiveFilters()
      ?'<div style="font-size:13px;font-weight:600;color:var(--navy);margin-bottom:6px">No runs match these filters</div>'
        +'<div style="font-size:12px;color:var(--gray);line-height:1.7;max-width:460px;margin:0 auto">You have started '+all.length+' run'+(all.length===1?'':'s')+'. '
        +'<button onclick="resetMrFilters()" style="background:none;border:none;padding:0;font:inherit;font-weight:700;color:#0d9488;cursor:pointer;text-decoration:underline">Clear all filters</button> to see '+(all.length===1?'it':'them')+'.</div>'
      :'<div style="font-size:13px;font-weight:600;color:var(--navy);margin-bottom:6px">No runs yet</div>'
        +'<div style="font-size:12px;color:var(--gray);line-height:1.7;max-width:460px;margin:0 auto">Journeys you start from <strong>AI Executive</strong> appear here and stay here — active and completed alike — even once they move on to someone else.</div>')
    +'</td></tr>';

  return '<div class="lp-page">'
    +'<div class="listing-head">'
    +'<div class="lp-filter-bar" style="flex:1;min-width:0;padding:0">'
    +'<div class="lp-filter-bar-label">Select Filter</div>'
    +'<div class="lp-filter-bar-row">'
    +apCS('mr-f-journey',[mrAnyOption.journey].concat(mrDistinct(all,function(r){return r.journeyName;})),mrJourneyFilter,mrAnyOption.journey)
    +apCS('mr-f-mode',[mrAnyOption.mode].concat(mrDistinct(all,function(r){return r.mode;})),mrModeFilter,mrAnyOption.mode)
    +'<input class="ct-search-input" id="mr-search-input" type="text" placeholder="Search runs..." title="Matches run ID, subject, journey, current step and its owner" value="'+attrSafe(mrSearchQuery)+'" style="flex:0 1 210px;min-width:150px;height:34px;border-radius:20px" onkeydown="if(event.key===\'Enter\')applyMrSearch()">'
    +'<button class="lp-pill-reset" onclick="resetMrFilters()">Reset</button>'
    +'<button class="lp-pill-search" onclick="applyMrSearch()">Search</button>'
    +'</div></div>'
    +'<div class="listing-stats">'
    +statTile('In Progress',counts['In Progress'],'#2563eb')
    +statTile('Waiting Approval',counts['Waiting Approval'],'#b45309')
    +statTile('Needs Attention',counts['Needs Attention'],'#dc2626')
    +statTile('Completed',counts.Completed,'#16a34a')
    +'</div></div>'
    +'<div class="lp-table-card" style="margin-top:14px">'
    +'<table class="lp-table"><thead><tr>'
    +'<th>SR. NO</th><th>RUN ID</th><th>JOURNEY</th><th>SUBJECT</th><th>CURRENT STEP</th><th>STATUS</th><th>STARTED</th><th>ACTION</th>'
    +'</tr></thead><tbody>'+tableRows+'</tbody></table>'
    +(rows.length
      ?'<div class="lp-pagination">'
        +'<span class="lp-pagination-info">'+(rows.length===all.length
          ?'Showing all '+all.length+' run'+(all.length===1?'':'s')
          :'Showing '+rows.length+' of '+all.length+' run'+(all.length===1?'':'s'))+'</span>'
        +'<div class="lp-pagination-controls">'
        +'<button class="lp-pg-btn lp-pg-arrow" disabled><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg></button>'
        +'<button class="lp-pg-btn active">1</button>'
        +'<button class="lp-pg-btn lp-pg-arrow" disabled><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg></button>'
        +'</div></div>'
      :'')
    +'</div></div>';
}
function buildComplianceLiveQueuePanelHTML(){
  const runs=manualJourneyRuns.filter(function(r){
    if(r.journeyId!=='contract-creation'||r.status==='Completed')return false;
    const st=manualJourneySteps(r.journeyId)[r.currentStepIdx];
    return st&&st.ownerRole==='Compliance Officer';
  });
  const actionBtn=function(r){return '<button class="btn btn-primary btn-sm" onclick="event.stopPropagation();openComplianceHubForRun(\''+r.runId+'\')">Mark Complete</button>';};
  return manualRunListPanelHTML('Pending Compliance Checks',runs,'No contract journeys waiting on Compliance.',{actionBtn:actionBtn});
}
function buildHRLiveRunsPanelHTML(){
  const runs=manualJourneyRuns.filter(function(r){return r.journeyId==='contract-creation'&&r.currentStepIdx>=8&&r.status!=='Completed';});
  return manualRunListPanelHTML('Contract Journeys Ready for HR',runs,'No contract journeys have reached HR yet.');
}
// -- MANUAL MODE: "My Tasks" panel of manual-journey runs currently waiting on the active persona, across Contract Creation / Payroll Creation / H2R Lifecycle. Complements (does not replace) any journey-specific Dashboard queue panel, e.g. buildComplianceLiveQueuePanelHTML. --
function myPendingManualRuns(personaId){
  return manualJourneyRuns.filter(function(r){
    if(r.status==='Completed')return false;
    const st=manualJourneySteps(r.journeyId)[r.currentStepIdx];
    return st&&manualStepOwnerPersonaId(st.ownerRole)===personaId;
  });
}
// -- backPage defaults to 'my-tasks' for the queue callers that predate it; My Runs passes its own
// so Back off the fallback run page returns where the user actually came from. --
function openMyManualTask(runId,backPage){
  const run=getManualRun(runId);if(!run)return;
  const step=manualJourneySteps(run.journeyId)[run.currentStepIdx];
  if(step&&step.modulePage==='compliance'){openComplianceHubForRun(runId);return;}
  const tab=ctTabForManualStep(step);
  if(run.journeyId==='contract-creation'&&run.contractRecordId&&tab&&contractsData.some(function(c){return c.id===run.contractRecordId;})){
    navigatePage('contracts');
    openCtSidebar(run.contractRecordId,tab,null,run.runId);
    return;
  }
  if(step&&step.modulePage==='direct'){
    const emp=directEmpData.find(function(e){return e.onboardingRunId===runId;});
    if(emp){navigatePage('direct');openDeSidebar(emp.id);return;}
  }
  if(step&&step.modulePage==='payroll'){
    const emp=payrollEmpData.find(function(e){return e.readinessRunId===runId;});
    if(emp){navigatePage('payroll');openPrSidebar(emp.id,run.runId);return;}
  }
  selectedManualRunId=runId;manualJourneyBackPage=backPage||'my-tasks';page='manual-journey-run';renderADTPage();
}
function buildMyPendingManualTasksHTML(){
  const runs=myPendingManualRuns(activePersonaId);
  // -- Blockers/approvals on runs I own get the exception card + Resolve action (no Notify button here — I am the owner, not someone to nudge). Runs with nothing to resolve yet keep the plain progress card. --
  const queueItems=cockpitQueueItems(runs);
  const flagged={};
  queueItems.forEach(function(x){flagged[x.run.runId]=true;});
  const plainRuns=runs.filter(function(r){return !flagged[r.runId];});
  const exceptionsHTML=queueItems.map(function(x){
    return exceptionQueueCardHTML(x,{hideNotify:true,flagNotified:true,cardClick:"openManualRunPreviewModal('"+x.run.runId+"')"});
  }).join('');
  const actionBtn=function(r){return '<button class="btn btn-primary btn-sm" onclick="event.stopPropagation();openMyManualTask(\''+r.runId+'\')">Open</button>';};
  const plainHTML=plainRuns.length?'<div class="cockpit-run-list">'+plainRuns.map(function(r){return manualRunCardHTML(r,{actionBtn:actionBtn});}).join('')+'</div>':'';
  const body=(exceptionsHTML||plainHTML)
    ?(exceptionsHTML?'<div class="cockpit-ex-list" style="margin-bottom:'+(plainHTML?'14px':'0')+'">'+exceptionsHTML+'</div>':'')+plainHTML
    :'<div class="cockpit-empty-state">No manual-journey steps are waiting on you right now.</div>';
  return '<div class="dash-panel cockpit-run-panel"><div class="dash-panel-head"><div>Journeys Waiting On You</div></div>'+body+'</div>';
}
