function buildSalesDashboardHTML(p,tab){
  if(tab==='sales-approvals'){
    const openDealsCount=manualJourneyRuns.filter(function(r){return r.journeyId==='contract-creation'&&r.createdBy===p.id;}).length;
    return dashHeader('Deal Approvals Dashboard','Review proposal approvals, exceptions, and team deal movement.')
      +'<div class="stat-grid dash-stat-grid">'+dashStatNav('Open Deals',String(openDealsCount),'Owned by this role',null,dashIcoDoc,null,'toggleOpenDealsPanel()')+dashStatNav('Proposal Drafts','3','Ready for review','orange',dashIcoDoc)+dashStatNav('Client Responses','5','Awaiting acceptance','orange',dashIcoUser)+dashStatNav('Exceptions','1','Needs attention','red',dashIcoAlert)+'</div></div>';
  }
  /* == ACCOUNT MANAGER PAGE ==============================================================
     Three bands and nothing else: who I am (header), where everything is (rail), what to do
     next (listing). No stat tiles in any form. The first set was hardcoded; the set that
     replaced them was computed but still asserted headline counts a few inches above the rail
     that counts the same records by stage. Two numbers for one question is worse than either
     alone, so the rail is the only place the page counts anything. == */
  return '<div class="am-page">'
    +buildAmHeaderHTML(p)
    +buildAmPipelineHTML()
    +buildAmDealsListingHTML()
    +'</div>';
}
function buildAmHeaderHTML(p){
  /* No page title. The dashboard is the only thing on this route now, so a heading naming it
     would be a label for a page with nothing to distinguish it from. What earns the primary
     line instead is whose queue this is — the identity that scopes every figure below it.

     The four KPI tiles that sat opposite it are gone. They were filters over the same records
     the rail below already filters, and the rail is the better instrument: it covers every
     stage rather than three hand-picked cuts, and it does not put a second set of headline
     numbers on screen for the reader to reconcile against the first. */
  /* The one action this page was missing. An Account Manager's job starts with a client asking
     for people, and until now there was nowhere on their own page to log that — the only route
     in was the + on the Contracts listing, two navigations away. It opens the rebuilt
     contract-creation journey (js/contract-journey.js), which is stage 1 of this same rail. */
  return '<div class="am-head">'
    +'<div class="am-head-left">'
      +'<div class="am-head-title">'+p.name+' <span class="am-head-role">'+p.label+'</span></div>'
      +'<div class="am-head-sub">You are looking after '+amDeals.length+' pieces of work.</div>'
    +'</div>'
    +'<button class="am-head-new" onclick="ccjStartNewRun()">'
      +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>'
      +'New request</button>'
    +'</div>';
}
/* Ten rows a page, matching the rest of the app. Changing page closes any open drawer, since
   the record it describes is by definition no longer in the table. */
function amGoToPage(n){
  // The marker is about the row you came back to; a new page is a new set of rows.
  amPage=Math.max(1,n);amSelectedDealId=null;amReturnedDealId=null;
  renderADTPage();
}
function amListPaginationHTML(total,totalPages,start){
  const prev='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg>';
  const next='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg>';
  const buttons=Array.from({length:totalPages},function(_,i){
    return '<button class="lp-pg-btn'+(amPage===i+1?' active':'')+'" onclick="amGoToPage('+(i+1)+')">'+(i+1)+'</button>';
  }).join('');
  return '<div class="lp-pagination">'
    +'<span class="lp-pagination-info">Showing '+(total===0?0:start+1)+'&ndash;'+Math.min(start+AM_PAGE_SIZE,total)+' of '+total+' entries</span>'
    +'<div class="lp-pagination-controls">'
    +'<button class="lp-pg-btn lp-pg-arrow" onclick="amGoToPage('+(amPage-1)+')"'+(amPage===1?' disabled':'')+'>'+prev+'</button>'
    +buttons
    +'<button class="lp-pg-btn lp-pg-arrow" onclick="amGoToPage('+(amPage+1)+')"'+(amPage===totalPages?' disabled':'')+'>'+next+'</button>'
    +'</div></div>';
}

/* == ACCOUNT MANAGER — CLIENT PIPELINE ===================================================
   One horizontal rail of the nine client-facing statuses, then the records behind whichever
   stage is selected. The rail is grouped rather than flat: the five engagement stages happen
   once per client request, the four placement stages repeat per hire, and a client reading a
   flat row of nine boxes has no way to know that. The divider between the two groups carries
   that "repeats per hire" fan-out, so the shape of the pipeline explains itself.

   The deposit stage is a payment gate — the one place in this flow where the whole placement
   stalls on something the client owes us. The rail no longer marks it with a badge; the
   drawer's client-facing view spells it out in words, which is the surface where a reader has
   room to be told. == */
/* == THE RAIL ============================================================================
   Nine segments that divide the available width with flex:1 and min-width:0, which is the
   whole point: the previous version used fixed 134px cards inside a horizontal scroller, so
   stages 8 and 9 were off-screen and the pipeline stopped being a pipeline — you cannot read
   a sequence you have to scroll to finish. Flex division means it fits at any width by
   construction and there is no overflow to scroll.

   The cost of fitting is label length, so the segments carry the SHORT status and the full
   client-facing sentence moves to the listing header, where it is needed once rather than
   nine times, and to the tooltip. Counts stay because they are why anyone looks here.

   A segment is now three things: a count, a name, and a rule above it. The step number and
   the C / G corner badges are gone. The number was ordinal information the rail already
   states by being a left-to-right sequence, and the badges were single letters that had to
   be decoded — a legend the page never printed. Both meanings survive in the tooltip, which
   is where a label nobody can read on sight belonged in the first place. == */
function amSegmentHTML(s){
  const count=amStageCount(s.id);
  const selected=amPipelineStage===s.id;
  const flagTitle=s.gate?' · payment gate':s.clientAction?' · waiting on client':'';
  return '<button type="button" class="am-seg tone-'+s.tone+(selected?' selected':'')+(count?'':' empty')+'"'
    +' onclick="amSelectPipelineStage(\''+s.id+'\')"'
    +' title="'+attrSafe(String(s.label).replace(/&mdash;/g,'—')+flagTitle+' — '+String(s.internal).replace(/&mdash;/g,'—'))+'">'
    +'<span class="am-seg-bar"></span>'
    +'<span class="am-seg-top"><span class="am-seg-count">'+count+'</span></span>'
    +'<span class="am-seg-label">'+s.short+'</span>'
    +'</button>';
}
/* The two halves carry no heading of their own any more — the dashed divider is enough to show
   that the sequence changes character there, and the tour explains what changes. The track's
   own wording survives as the group tooltip and as the tour copy, which is where a user goes
   when they actually want the explanation. */
function amTrackGroupHTML(track,idx){
  const stages=amPipelineStages.filter(function(s){return s.track===track.id;});
  return '<div class="am-bar-group" style="flex:'+stages.length+'"'
    +' title="'+attrSafe(track.label+' — '+track.plain)+'">'
    +stages.map(amSegmentHTML).join('')+'</div>';
}
function buildAmPipelineHTML(){
  return '<div class="am-bar-card">'
    +'<div class="am-bar">'+amTrackGroupHTML(amPipelineTracks[0],0)+'<span class="am-bar-div"></span>'+amTrackGroupHTML(amPipelineTracks[1],1)+'</div>'
    +'</div>';
}
// Changing the stage drops any open record drawer: the row it belonged to is usually filtered out.
function amSelectPipelineStage(id){
  amPipelineStage=amPipelineStage===id?'':id;
  amSelectedDealId=null;amReturnedDealId=null;amPage=1;
  renderADTPage();
}
function amClearPipelineStage(){
  amPipelineStage='';amSelectedDealId=null;amPage=1;
  renderADTPage();
}
/* == THE LISTING =========================================================================
   Six columns, no min-width, so nothing is ever off-screen. Getting there meant deciding what
   an Account Manager actually triages on, and everything else went to the drawer:

     kept   Client (who) · Candidate/Scope (what) · Stage + sub-status (where exactly) ·
            Owner (who is holding it) · Age (is it late)
     moved  Value, full date, country as its own column, Ref ID as its own column
     cut    S.No — a row counter that costs a column and answers nothing

   Two merges did most of the work. Client Sees and Sub-status became one cell, because the
   parent stage and the step inside it are one fact read together, and repeating the parent in
   its own column is dead width. Owner moved out of the sub-status cell into its own narrow
   column, which is what let the sub-status text stop truncating. == */
function buildAmDealsListingHTML(){
  const hamburger='<svg width="16" height="14" viewBox="0 0 18 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="1" y1="2" x2="17" y2="2"/><line x1="1" y1="7" x2="17" y2="7"/><line x1="1" y1="12" x2="17" y2="12"/></svg>';
  const stage=amPipelineStage?amStageById(amPipelineStage):null;
  const all=amFilteredDeals();
  const total=all.length;
  // Clamp rather than trust: a filter or a completed step can shrink the result set while the
  // user is on a later page, and an out-of-range page would render an empty table over real data.
  const totalPages=Math.max(1,Math.ceil(total/AM_PAGE_SIZE));
  if(amPage>totalPages)amPage=totalPages;
  if(amPage<1)amPage=1;
  const start=(amPage-1)*AM_PAGE_SIZE;
  const rows=all.slice(start,start+AM_PAGE_SIZE);
  // Validated against the visible page, not the whole result set — a drawer describing a record
  // that is not in the table under it reads as a bug.
  if(amSelectedDealId&&!rows.some(function(d){return d.id===amSelectedDealId;}))amSelectedDealId=null;
  const title=stage?stage.short:'All your work';
  /* "Click a step above" pointed at the rail, and the rail is nine STAGES — the steps are the
     three-to-six sub-statuses inside each one, which live in this table and in the drawer. One
     word, but it was the word that taught a new reader the wrong name for the thing they were
     about to click, and the same reader then met "Stage 2 of 9 · step 5 of 6" in every row. */
  const sub=stage
    ?String(stage.plain).replace(/&mdash;/g,'—')
      +' &nbsp;·&nbsp; Stage '+stage.n+' of '+amPipelineStages.length
      +' &nbsp;·&nbsp; Should take: '+(amStageSla[stage.id]||'&mdash;')
    :'Everything you own, in one list. Pick a stage above to narrow it down.';
  /* One list defines the columns, and the colgroup, the header row and every cell are all
     generated from it. That is the fix for a real bug: the drawer-open view used to hide two
     columns with `display:none` while leaving all six <col> elements in place, and under
     table-layout:fixed the browser maps the Nth *rendered* cell to the Nth <col>. So the four
     surviving cells silently took the widths of cols 1-4 (34% / 0% / 36% / 0%), collapsing
     "Where it is now" and the action button to nothing and stranding 30% of empty table on the
     right. Generating both sides from one source makes that class of drift impossible. */
  const compact=!!amSelectedDealId;
  const columns=[
    {w:'19%',cw:'32%',th:'Client',
     cell:function(d){return '<div class="cell-primary am-c-client">'+d.client+'</div><div class="cell-sub">'+d.ref+'</div>';}},
    /* "Who we are placing" asked for a person and got "4 roles" on more than half the rows —
       an engagement has no named hire yet, which is the whole reason it is an engagement. "The
       hire" holds both: a headcount being quoted and a person being onboarded are the same
       column answering "what is being hired", and the line under it says the job and where. */
    {w:'18%',hideWhenCompact:true,th:'The hire',thTitle:'The headcount on a client request, or the person on a placement',
     cell:function(d){return '<div class="cell-primary am-c-client">'+d.subject+'</div><div class="cell-sub">'+d.role+' &middot; '+d.country+'</div>';}},
    {w:'27%',cw:'36%',th:'Where it is now',thTitle:'The stage the client sees, the step being worked, and how far in that is',cell:amSubCellHTML},
    {w:'9%',hideWhenCompact:true,th:'Days',thTitle:'Days sitting on the current step',
     cell:function(d){return '<span class="am-c-age'+(d.breach?' breach':'')+'">'+d.age+'d</span>'
       +(d.breach?'<div class="cell-sub am-c-late">Too long</div>':'');}},
    {w:'14%',cw:'18%',th:'What to do next',cell:amNextActionCellHTML},
    // The way into the deal's run sits at the END of the row — same design as everywhere, sized
    // for a cell — with the drawer's hamburger beside it. It moved here from the drawer's Logs
    // panel: two clicks to reach a button that opens something else was one too many.
    //
    // Not on Working. An active placement's journey is finished — payroll runs on the calendar,
    // not on a run — so a run button there would open nine settled stages with nothing live to
    // do, and a control that opens nothing to act on teaches people to stop pressing it.
    {w:'13%',cw:'14%',th:'',
     cell:function(d){return '<div class="am-row-end">'
       +'<button class="lp-action-btn" onclick="event.stopPropagation();openAmDealSidebar('+d.id+')" title="Open this record">'+hamburger+'</button>'
       +(d.stage==='active'?'':ccjOpenRunBtnHTML(d,true))
       +'</div>';}}
  ].filter(function(c){return !(compact&&c.hideWhenCompact);});
  const colgroup='<colgroup>'+columns.map(function(c){return '<col style="width:'+(compact?c.cw:c.w)+'">';}).join('')+'</colgroup>';
  const head='<thead><tr>'+columns.map(function(c){return '<th'+(c.thTitle?' title="'+attrSafe(c.thTitle)+'"':'')+'>'+c.th+'</th>';}).join('')+'</tr></thead>';
  const body=rows.length?rows.map(function(d){
    // Two reasons a row is marked, and they are not the same thing: `lp-row-selected` is the record
    // currently open in the drawer, `am-row-returned` is the row a run was just opened from. The
    // second changes nothing about the table's shape — see amReturnedDealId.
    return '<tr class="am-row'+(amSelectedDealId===d.id?' lp-row-selected':'')
      +(amReturnedDealId===d.id&&amSelectedDealId!==d.id?' am-row-returned':'')
      +'" id="am-row-'+d.id+'" style="cursor:pointer" onclick="openAmDealSidebar('+d.id+')">'
      +columns.map(function(c){return '<td>'+c.cell(d)+'</td>';}).join('')
      +'</tr>';
  }).join('')
    // An empty table under a stage filter is not the same fact as an empty queue, and one
    // sentence for both left the reader checking the rail to find out which they were looking at.
    :'<tr><td colspan="'+columns.length+'" style="padding:34px;text-align:center;color:var(--gray);font-size:12.5px">'
      +(stage?'Nothing is sitting at &ldquo;'+stage.short+'&rdquo; right now.':'Nothing here right now.')
      +'</td></tr>';
  return '<div class="am-list-block">'
    +'<div class="am-list-head">'
      +'<div><div class="am-list-title">'+title+'</div><div class="am-list-sub">'+sub+'</div></div>'
      // "3 of 19" on its own never said of what. The tooltip says it once rather than spending
      // table width on the words.
      +'<div class="am-list-right"><span class="am-list-count" title="'+attrSafe(total+' shown of the '+amDeals.length+' pieces of work you own')+'">'+total+' of '+amDeals.length+'</span>'
      +(stage?'<button class="lp-pill-reset" onclick="amClearPipelineStage()">Show all</button>':'')+'</div>'
    +'</div>'
    +'<div class="lp-split-wrap"><div class="lp-split-main">'
    +'<table class="lp-table am-table">'+colgroup+head+'<tbody>'+body+'</tbody></table>'
    +amListPaginationHTML(total,totalPages,start)
    +'</div>'
    +'<div class="lp-split-sb'+(amSelectedDealId?' open':'')+'" id="am-split-sb"><div class="lp-isb" id="am-isb-inner">'+(amSelectedDealId?renderAmDealSidebar():'')+'</div></div>'
    +'</div></div>';
}
// The badge palette reuses the listing's existing status classes so this table reads
// identically to every other listing in the app; only the stage->tone mapping is new.
function amBadgeClass(stageId){
  const s=amStageById(stageId);if(!s)return 'pending';
  if(s.tone==='green')return 'approved';
  if(s.tone==='red')return 'inactive';
  if(s.tone==='amber')return 'pending';
  return 'expired';
}
/* == SUB-STATUS CELL + POPOVER ===========================================================
   The listing cell answers "how far into this stage" in one glance — current sub-step and
   n of m — and the popover carries the same numbered treatment as the Contracts status menu
   so it reads as one product rather than a bolted-on panel.

   Unlike that menu, this one is owner-gated. Only the single NEXT sub-step is actionable, and
   only when the signed-in role owns it; everything else states who is holding it. The existing
   Contracts picker lets any role click any future step (see buildContractsListingHTML), which
   makes the owner and SLA columns of the operating model unenforceable — not a pattern to
   copy into a surface that now carries per-step ownership. == */
/* Read-only now. The 41-step popover that used to hang off this cell was the opposite of
   "show me the next action" — it presented every step of the stage and made the user work out
   which one mattered. The single step in progress is the answer, and everything else moved
   into the drawer, where Logs carries the action and Workflow carries the history. */
function amSubCellHTML(d){
  const s=amStageById(d.stage)||{};
  const steps=amSubSteps(d.stage);
  if(!steps.length)return '<span class="lp-dash">&mdash;</span>';
  // A terminal stage is a STATE, not a position. "Active ⚡AUTO · Step 3 of 3" dressed a finished
  // placement in mid-flight machinery — a step counter with nothing left to count and an auto tag
  // with nothing left to run. Done reads as done: the pill and one settled fact.
  if(s.terminal){
    return '<div class="am-where" title="'+attrSafe(String(s.plain).replace(/&mdash;/g,'—'))+'">'
      +'<span class="am-sub-pill '+amBadgeClass(d.stage)+'">'+s.short+'</span>'
      +'<span class="am-where-step am-where-done">'
      +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>'
      +'Employed and on payroll</span>'
      // The one row where "of 9" is the whole point: this is the ninth, and saying so is what
      // separates a journey that finished from a stage that happens to have run out of steps.
      +'<span class="am-where-prog">Stage '+amJourneyPos(d).stageNo+' of '+amPipelineStages.length+' &middot; all done</span>'
      +'</div>';
  }
  const idx=amSubIndex(d);
  const cur=steps[idx];
  return '<div class="am-where"'
    +' title="'+attrSafe(String(s.plain).replace(/&mdash;/g,'—'))+'">'
    +'<span class="am-sub-pill '+amBadgeClass(d.stage)+'">'+s.short+'</span>'
    +'<span class="am-where-step">'+cur.label+(cur.auto?'<span class="am-sub-tag auto">'+amBoltSvg+' auto</span>':'')+(cur.cond?'<i class="am-sub-cond">'+cur.cond+'</i>':'')+'</span>'
    // Journey first, stage second — see amProgressText. "Step 3 of 3" alone had a brand new
    // request reading as a completed one.
    +'<span class="am-where-prog">'+amProgressText(d)+'</span>'
    +'</div>';
}
/* The one column a new user should be able to act from without reading anything else. */
const amBoltSvg='<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2 3 14h7l-1 8 10-12h-7l1-8z"/></svg>';
function amNextActionCellHTML(d){
  const a=amNextAction(d);
  // A finished placement's next action belongs to the calendar, not to a person or an agent —
  // "⚡ Auto" here claimed machinery was about to do something when nothing is left to do.
  const st=amStageById(d.stage);
  if(st&&st.terminal)return '<span class="am-act wait">Payroll on schedule</span>';
  // Auto steps get a passive marker in the listing — there is nothing here for a person to do,
  // and a button would say otherwise. The drawer carries the demo-only "run it now" control.
  if(a.kind==='auto')return '<span class="am-act auto">'+amBoltSvg+' Auto</span>';
  if(a.kind==='do')return '<button class="am-act do" onclick="event.stopPropagation();amCompleteStep('+d.id+')">'
    +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2"><polyline points="20 6 9 17 4 12"/></svg> '+a.label+'</button>';
  if(a.kind==='chase')return '<button class="am-act chase" onclick="event.stopPropagation();amRemindClient('+d.id+')">'
    +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M4 4h16v12H7l-3 3z"/></svg> '+a.label+'</button>';
  return '<span class="am-act wait">'+a.label+'</span>';
}
// Stage-level SLA straight off the operating model, kept beside the stages it annotates.
const amStageSla={'request-received':'1 hour','quote-prep':'1 day, or 2 if a partner is involved','quote-review':'Follow up every few days','quote-approved':'Same day','agreement-signature':'2 days','deposit-due':'Clears automatically when paid','employment-contract':'1 day to issue','onboarding':'Depends on the country','active':'Next payroll run'};
function amStampToday(d){
  const now=new Date();
  d.updated=now.getDate()+' '+amMonths[now.getMonth()]+' '+now.getFullYear();
  d.age=0;
}
/* Shared body behind both the real completion and the simulated one. */
function amAdvanceStep(dealId,simulated){
  const d=amDeals.find(function(x){return x.id===dealId;});if(!d)return;
  const steps=amSubSteps(d.stage);
  const idx=amSubIndex(d);
  const cur=steps[idx];if(!cur)return;
  // The ownership gate still stands for a real completion. Simulation is the demo's stand-in
  // for the webhook, e-signature callback or other team that would move this step in
  // production, so it deliberately bypasses the gate — and says so in the toast, so a
  // simulated advance is never mistaken for the owner having actually done it.
  if(!simulated&&!amCanAdvance(cur.owner)){showAiToast('Not yours to complete','&ldquo;'+cur.label+'&rdquo; belongs to '+cur.owner+'.');return;}
  const who=amOwnerInfo(cur.owner).who;
  // The comment travels with the completion — same contract as every other Logs form in the
  // app: the note is written by the person acting, at the moment of acting.
  const commentEl=document.getElementById('am-log-comment');
  const comment=commentEl?commentEl.value.trim():'';
  // Required on a real completion, same as every other Logs form; a simulated handoff is the
  // demo standing in for someone else, so it is exempt.
  if(!simulated&&commentEl&&!comment){showAiToast('A comment is required','Add a note for this action before marking it done.');commentEl.focus();return;}
  d.breach=false;amStampToday(d);
  const wasLast=idx>=steps.length-1;
  const stageBefore=d.stage;
  if(!wasLast){d.sub=idx+1;}
  else{
    const nextStage=amPipelineStages[amStageIndex(d.stage)+1];
    if(nextStage){d.stage=nextStage.id;d.sub=0;}
  }
  // The system sweeps through whatever automated steps come next, so the record lands on the
  // next HUMAN step — the auto work is reported, never offered as a task.
  const autoRan=amSkipAutoSteps(d);
  if(comment)amPushNote(d,'Note on &ldquo;'+cur.label+'&rdquo;',comment);
  const landed=amCurrentSub(d);
  const autoMsg=autoRan.length?' Automation ran: '+autoRan.join(', ')+'.':'';
  if(d.stage!==stageBefore){
    const st=amStageById(d.stage);
    showAiToast('Moved to &ldquo;'+st.short+'&rdquo;',d.ref+' &middot; the client now sees &ldquo;'+String(st.label).replace(/&mdash;/g,'—')+'&rdquo;.'+autoMsg);
  }else if(landed&&landed!==cur){
    showAiToast(simulated?'Simulated &mdash; '+cur.label:cur.label+' &mdash; done',
      (simulated?who+' completed this. ':'')+d.ref+' &middot; next up: '+landed.label+'.'+autoMsg);
  }else{
    showAiToast('All done',d.ref+' is employed and on payroll.'+autoMsg);
  }
  renderADTPage();
}
/* One action, one meaning: finish the step this record is sitting on. If it was the last step
   of the stage, the record moves to the next stage — the client-facing status is always a
   consequence of the steps underneath it, never set on its own. */
function amCompleteStep(dealId){amAdvanceStep(dealId,false);}
// Stands in for the party that owns the step when that party is not the signed-in user, so a
// demo can walk the whole nine-stage journey without switching persona at every handoff.
function amSimulateStep(dealId){amAdvanceStep(dealId,true);}
/* The useful action on a step the client owns. It does not move the record — it records that
   we chased, which is exactly the thing an Account Manager needs evidence of later. */
function amRemindClient(dealId){
  const d=amDeals.find(function(x){return x.id===dealId;});if(!d)return;
  const cur=amCurrentSub(d)||{};
  const stage=amStageById(d.stage)||{};
  const now=new Date();
  const h=now.getHours();
  (amExtraLog[d.id]=amExtraLog[d.id]||[]).unshift({
    stage:stage,stageNo:stage.n,subNo:amSubIndex(d)+1,
    sub:{label:'Reminder sent to client'},
    owner:amOwnerInfo('Account Manager'),ownerRole:'Account Manager',
    state:'note',reminder:true,
    date:now.getDate()+' '+amMonths[now.getMonth()]+' '+now.getFullYear(),
    time:(h%12||12)+':'+String(now.getMinutes()).padStart(2,'0')+' '+(h>=12?'PM':'AM'),
    note:'Chased &ldquo;'+cur.label+'&rdquo;.'
  });
  showAiToast('Reminder sent',d.client+' &middot; chased &ldquo;'+cur.label+'&rdquo;.');
  renderADTPage();
}
function openAmDealSidebar(id){
  // Opening a record supersedes the came-back-to marker — the drawer is a stronger statement about
  // which row matters than a highlight is, and showing both would mark two rows at once.
  amSelectedDealId=id;amReturnedDealId=null;amDealTab='basic-details';
  const sb=document.getElementById('am-split-sb');if(sb)sb.classList.add('open');
  const inner=document.getElementById('am-isb-inner');if(inner)inner.innerHTML=renderAmDealSidebar();
  document.querySelectorAll('.am-row').forEach(function(r){r.classList.toggle('lp-row-selected',r.id==='am-row-'+id);});
}
function closeAmDealSidebar(){
  amSelectedDealId=null;
  const sb=document.getElementById('am-split-sb');if(sb)sb.classList.remove('open');
  document.querySelectorAll('.am-row').forEach(function(r){r.classList.remove('lp-row-selected');});
}
function navAmDealTab(tab){
  amDealTab=tab;
  const inner=document.getElementById('am-isb-inner');if(inner)inner.innerHTML=renderAmDealSidebar();
}
/* The drawer's second tab is the point of the whole screen: the same nine stages the rail
   shows, but walked for one record, worded exactly as the client is shown them. An Account
   Manager on a call needs to answer "where are we and what are you waiting on me for" —
   which is a per-record question the rail can't answer. */
/* == THE RECORD DRAWER ===================================================================
   Four tabs, and the split between the middle two is the point of it:

     Details          the facts about this record
     Logs             where you ACT, and the fine-grained trail of every step event
     Workflow         the coarse story — which of the nine stages are done, who finished them
     What client sees the client mirror, with no internal steps in it at all

   Logs and Workflow are not two views of one list. Logs is every step event including the ones
   that did not move the record (a chase, a reminder) and it is the only place that can change
   the record. Workflow is stage-level and read-only: nine rows, the shape of the journey. That
   is the same division the rest of this app already uses between its Logs and Workflow tabs,
   so a user who has read one record here can read any record anywhere. */
function renderAmDealSidebar(){
  const d=amDeals.find(function(x){return x.id===amSelectedDealId;});if(!d)return '';
  const s=amStageById(d.stage)||{};
  const tabs=[{id:'basic-details',label:'Details'},{id:'logs',label:'Logs'},{id:'workflow',label:'Workflow'},{id:'client-view',label:'What client sees'}];
  const tabBar='<div class="lp-isb-tabbar">'
    +'<div class="lp-isb-tabs" id="am-isb-tabs">'+tabs.map(function(t){return '<button class="lp-isb-tab'+(amDealTab===t.id?' active':'')+'" onclick="navAmDealTab(\''+t.id+'\')">'+t.label+'</button>';}).join('')+'</div>'
    +'<div class="lp-isb-right"><button class="lp-isb-close" onclick="closeAmDealSidebar()" title="Close"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>'
    +'</div>';
  const iId='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 3H8a2 2 0 0 0-2 2v2h12V5a2 2 0 0 0-2-2z"/></svg>';
  const iUser='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
  const iGlobe='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>';
  const iMoney='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>';
  const iClock='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
  const iTag='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>';
  const fc=function(ico,label,val){return '<div class="lp-sb-field-card"><div class="lp-sb-field-icon">'+ico+'</div><div class="lp-sb-field-content"><div class="lp-sb-field-label">'+label+'</div><div class="lp-sb-field-value">'+val+'</div></div></div>';};
  let body='';

  if(amDealTab==='basic-details'){
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">'+d.client+'</span>'
      +'<span class="lp-status-badge '+amBadgeClass(d.stage)+'">'+s.short+'</span></div>'
      +'<div class="am-sb-plain">'+s.plain+'</div>'
      +'<div class="lp-sb-detail-grid">'
      +fc(iId,'Reference',d.ref)+fc(iTag,'Type of record',d.kind==='engagement'?'A client request':'One person being hired')
      +fc(iUser,d.kind==='engagement'?'How many roles':'Person',d.subject)+fc(iUser,'Job',d.role)
      +fc(iGlobe,'Country',d.country)+fc(iMoney,'Worth','<span style="color:var(--orange)">'+d.value+'</span>')
      +fc(iClock,'Last touched',d.updated)+fc(iClock,'Days on this step',d.age+' day'+(d.age===1?'':'s'))
      +'</div>';

  }else if(amDealTab==='logs'){
    /* The action lives here, at the top, above the trail it writes into. One step, one button —
       the same next action the listing shows, so the two can never disagree. */
    const a=amNextAction(d);
    const steps=amSubSteps(d.stage);
    const idx=amSubIndex(d);
    const own=amOwnerInfo(a.owner);
    const mine=a.kind==='do';
    // Reachable only in the terminal stage: everywhere else amSkipAutoSteps guarantees the
    // record rests on a human step, so the Logs never ask anyone to advance automation.
    const isAuto=a.kind==='auto';
    /* The standard Logs action panel — header, ownership line, comment, one button — the same
       shape as the Contracts drawer, so advancing a deal reads like advancing anything else in
       the app. When the step is the signed-in role's, the button completes it for real; anyone
       else's is simulated so the demo can walk every handoff. The reminder survives as a
       secondary link on client-owned steps: it is a real AM action and moves nothing. */
    const simLabel=a.step&&a.step.decision?'Simulate: '+own.who+' approves':'Simulate: '+own.who+' completes this';
    const actionPanel=isAuto
      ?'<div class="lp-logs-form">'
        +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:var(--navy);display:inline-block;flex-shrink:0"></span>Runs automatically</div>'
        +'<p class="lp-logs-form-sub">&ldquo;'+a.step.label+'&rdquo; is performed by the AI Execution Layer'+(a.step.autoNote?' &mdash; '+a.step.autoNote:'')+'. Nothing to do here.</p>'
        +'</div>'
      :'<div class="lp-logs-form">'
        +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:#f59e0b;display:inline-block;flex-shrink:0"></span>Next: '+a.step.label+'</div>'
        +'<p class="lp-logs-form-sub">'
          +(mine?'This step is yours to complete.':a.kind==='chase'?'Waiting on the client.':'Owned by '+own.who+' ('+a.owner+').')
          +' Step '+(idx+1)+' of '+steps.length+' in &ldquo;'+s.short+'&rdquo;'
          +(a.step.sla?' &middot; should take '+a.step.sla:'')+'.</p>'
        +'<div class="lp-logs-form-label">Comment'+(mine?' <span class="lp-logs-form-req">*</span>':'')+'</div>'
        +'<textarea id="am-log-comment" class="lp-logs-form-textarea" placeholder="Add a note for this action..."></textarea>'
        +(mine
          ?'<button class="lp-logs-save-btn" onclick="amCompleteStep('+d.id+')">Mark &ldquo;'+a.step.label+'&rdquo; done</button>'
          :'<button class="lp-logs-save-btn" onclick="amSimulateStep('+d.id+')">'+simLabel+'</button>'
            +(a.kind==='chase'?'<button class="am-sb-chase-link" onclick="amRemindClient('+d.id+')">Send the client a reminder instead</button>':''))
        // The way into the deal's run lives at the end of the LISTING ROW, not here — the Logs
        // panel keeps to its one job, completing the step in front of you.
        +'</div>';
    /* The "Manual steps in <stage>" checklist that used to sit above the trail is gone. Logs is
       the action tab: one thing to do, and the record of what has been done. The checklist was a
       third thing — a read-only preview of the steps still to come — and it restated the step
       the action panel already names, one line below the panel's own "Step n of m". The full
       sequence, with its owners and its automated steps, lives in the Workflow tab, which is the
       tab whose job is answering "what does this stage consist of". */
    const log=amDealLog(d);
    const personSvg='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
    const calSvg='<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
    const clkSvg='<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
    const timeline=log.length?log.map(function(e,i){
      const sk=e.reminder?'default':e.state==='current'?'default':'active';
      return '<div class="lp-log-row">'
        +'<div class="lp-log-avatar-col"><div class="lp-log-avatar lp-log-avatar--'+sk+'">'+personSvg+'</div>'+(i<log.length-1?'<div class="lp-log-connector"></div>':'')+'</div>'
        +'<div class="lp-log-card">'
        +'<div class="lp-log-status-row"><span class="lp-log-dot lp-log-dot--'+sk+'"></span>'
          +'<span class="lp-log-status-text lp-log-status-text--'+sk+'">'+e.sub.label+'</span>'
          +(e.sub.auto?'<span class="am-sub-tag auto">'+amBoltSvg+' auto</span>':'')
          +(e.reminder?'<span class="am-sub-tag loop">reminder</span>':'')
          +(e.state==='current'?'<span class="am-sub-tag loop">happening now</span>':'')
          +(e.breach?'<span class="am-sub-tag breach">took too long</span>':'')+'</div>'
        // The doer in the trail is whoever actually did it — the layer for auto steps.
        +'<div class="lp-log-meta-row"><span class="lp-log-meta-item">'+personSvg+'<span>'+(e.sub.auto?'AI Execution Layer':e.owner.who)+'</span></span>'
          +'<span class="lp-log-meta-item">'+calSvg+'<span>'+e.date+'</span></span>'
          +'<span class="lp-log-meta-item">'+clkSvg+'<span>'+e.time+'</span></span></div>'
        +'<div class="lp-log-comment-row"><span class="lp-log-comment-label">In:</span>'+e.stageNo+'. '+e.stage.short
          +' &middot; '+(e.note?e.note:e.state==='current'?'In progress.':'Finished.')+'</div>'
        +'</div></div>';
    }).join(''):'<div class="lp-logs-empty">Nothing has happened yet.</div>';
    // Standard logs layout: trail on the left, sticky action panel on the right — the exact
    // arrangement of every other Logs tab in the app.
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">'+d.ref+' &middot; '+d.subject+'</span>'
      +'<span class="am-int-chip">Internal</span></div>'
      +'<div class="am-sb-loghead">Everything that has happened <span>'+log.length+' entr'+(log.length===1?'y':'ies')+', newest first</span></div>'
      +'<div class="lp-logs-wrap"><div class="lp-logs-timeline">'+timeline+'</div>'+actionPanel+'</div>';

  }else if(amDealTab==='workflow'){
    /* Stage-level and read-only: the nine steps of the journey, which are done, which one is
       live, and who finished each. This is the answer to "what has been done to get here". */
    const curIdx=amStageIndex(d.stage);
    const log=amDealLog(d);
    const rows=amPipelineStages.map(function(st,i){
      const state=i<curIdx?'done':i===curIdx?'current':'upcoming';
      const steps=amSubSteps(st.id);
      const doneCount=i<curIdx?steps.length:i===curIdx?amSubIndex(d)+1:0;
      // Who last touched this stage, taken from the derived trail rather than restated.
      const last=log.filter(function(e){return e.stage.id===st.id&&!e.reminder;})[0];
      const mark=state==='done'?'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2"><polyline points="20 6 9 17 4 12"/></svg>':String(st.n);
      return '<div class="am-cv-row '+state+'">'
        +'<div class="am-cv-markcol"><div class="am-cv-mark">'+mark+'</div>'+(i<amPipelineStages.length-1?'<div class="am-cv-line"></div>':'')+'</div>'
        // How much of this stage runs itself — the count a PM scans for ("6 tasks, 4 auto"
        // says how much human time the stage really costs).
        +'<div class="am-cv-body"><div class="am-cv-label">'+st.short
          +(st.gate?'<span class="am-sub-tag breach">payment gate</span>':'')
          +(function(){const n=steps.filter(function(x){return x.auto;}).length;return n?'<span class="am-sub-tag auto">'+amBoltSvg+' '+n+' of '+steps.length+' auto</span>':'';})()
          +'</div>'
        +'<div class="am-cv-sub">'
          +(state==='done'?doneCount+' of '+steps.length+' tasks done'+(last?' &middot; last by '+last.owner.who+' on '+last.date:'')
            :state==='current'?'On task '+doneCount+' of '+steps.length+' &middot; '+(amCurrentSub(d)||{}).label
              +((amCurrentSub(d)||{}).auto?' &middot; runs automatically':' &middot; waiting on '+((amCurrentSub(d)||{}).owner||'&mdash;'))
            :'Not started &middot; '+steps.length+' tasks &middot; '+st.waitingOn)
        +'</div></div></div>';
    }).join('');
    /* == AUTOMATED BY THE SYSTEM =========================================================
       The automation lives HERE, not in the Logs: these are not tasks anyone will ever tick,
       they are facts the system produced — and facts can be revisited. The CSM assignment is
       the model case: assigned by client country the moment intake completed, shown with a
       Reassign control so the routing can be corrected without replaying anything. Only
       automation that has already run appears; upcoming automation would just be a promise. */
    const autoRan=[];
    amPipelineStages.forEach(function(st,si){
      if(si>curIdx)return;
      const upto=si<curIdx?amSubSteps(st.id).length:amSubIndex(d)+1;
      amSubSteps(st.id).slice(0,upto).forEach(function(sub){if(sub.auto)autoRan.push({stage:st,sub:sub});});
    });
    const csmOpts=amCsmPool.map(function(n){return '<option'+(n===amCsmFor(d)?' selected':'')+'>'+n+'</option>';}).join('');
    const autoRows=autoRan.map(function(x){
      const isCsm=x.sub.label==='CSM assigned';
      return '<div class="am-auto-row">'
        +'<span class="am-auto-bolt">'+amBoltSvg+'</span>'
        +'<span class="am-auto-txt"><b>'+x.sub.label+'</b><i>'+(x.sub.autoNote||'automated')+' &middot; in &ldquo;'+x.stage.short+'&rdquo;</i></span>'
        +(isCsm
          ?'<span class="am-auto-result"><select class="am-auto-select" onchange="amReassignCsm('+d.id+',this.value)">'+csmOpts+'</select></span>'
          :'<span class="am-auto-done">Done</span>')
        +'</div>';
    }).join('');
    const autoSection=autoRan.length
      ?'<div class="am-sb-steps" style="margin-top:14px">'
        +'<div class="am-sb-steps-head">Automated by the system<span>'+autoRan.length+' action'+(autoRan.length===1?'':'s')+'</span></div>'
        +autoRows
        +'</div>'
      :'';
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">How far this has got</span>'
      +'<span class="am-int-chip">Internal</span></div>'
      +'<div class="am-cv-intro">The nine steps every piece of work goes through, and what has already been done on this one. To change anything, use the Logs tab.</div>'
      +'<div class="am-cv-list">'+rows+'</div>'
      +autoSection;

  }else{
    /* Deliberately free of the internal tasks. This tab is the client mirror, and those tasks
       name partner sourcing, off-standard pricing approvals and sanctions screening — so the
       tab is labelled client-visible to make it obvious in a demo that nothing internal is on
       this screen by accident. */
    const cur=amStageIndex(d.stage);
    const steps=amPipelineStages.map(function(st,i){
      const state=i<cur?'done':i===cur?'current':'upcoming';
      const mark=state==='done'?'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2"><polyline points="20 6 9 17 4 12"/></svg>':String(st.n);
      const flag=st.gate?'<span class="am-stage-flag gate">Gate</span>':st.clientAction?'<span class="am-stage-flag client">Your turn</span>':'';
      return '<div class="am-cv-row '+state+'">'
        +'<div class="am-cv-markcol"><div class="am-cv-mark">'+mark+'</div>'+(i<amPipelineStages.length-1?'<div class="am-cv-line"></div>':'')+'</div>'
        +'<div class="am-cv-body"><div class="am-cv-label">'+st.label+flag+'</div>'
        +'<div class="am-cv-sub">'+(state==='current'?'Where you are now':state==='done'?'Done':'Still to come')+'</div></div>'
        +'</div>';
    }).join('');
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">'+d.ref+' &middot; '+d.subject+'</span>'
      +'<span class="am-int-chip client">Client-visible</span></div>'
      +'<div class="am-cv-intro">Exactly what '+d.client+' sees for this record &mdash; the nine headline stages only. The internal tasks under them are never shown here.</div>'
      +'<div class="am-cv-list">'+steps+'</div>';
  }
  return tabBar+'<div class="lp-isb-body">'+body+'</div>';
}
/* == OPS MANAGER — BHAIYAA STORE OPERATIONS ==============================================
   The Account Manager board's three bands, pointed at the Bhaiyaa Store Creation Journey:
   header (whose queue), rail (where everything is), listing (what to do next). It reuses that
   page's stylesheet wholesale rather than growing a parallel one — .am-* is a pipeline-board
   vocabulary, not an Account-Manager-only one, and two boards that are meant to read as one
   product should not be two stylesheets that drift.

   What is deliberately NOT here: stat tiles. The rail counts the same twelve records by stage
   a few inches below where tiles would sit, and one set of counts per page is the rule this
   pattern was built on. == */
function buildStoreOpsDashboardHTML(){
  // Load the synced stores the first time the board is opened, then re-render. Fetching on every
  // render would refetch on every drawer click; the Sync button below is how you ask again.
  if(!soLiveLoaded){
    soLoadLiveRuns().then(function(changed){if(changed&&page==='dashboard')renderADTPage();});
  }
  return '<div class="am-page">'
    +buildSoHeaderHTML()
    +buildSoPipelineHTML()
    +buildSoListingHTML()
    +'</div>';
}
/* -- Asks the backend to poll Bhaiyaa once, then reloads the board.
   A button rather than a timer: this is a real request to somebody else's staging box, and a
   board that quietly polls a third party every few seconds for the whole time it is open is
   traffic nobody asked for. Pressing it is also the honest demo — you sign up, you press Sync,
   the store appears. -- */
let soSyncing=false;
function soSyncFromBhaiyaa(){
  if(soSyncing)return;
  soSyncing=true;renderADTPage();
  execApiRequest('POST','/stores/poll').then(function(res){
    soSyncing=false;
    if(!res.ok){
      showAiToast('Could not reach Bhaiyaa',res.offline
        ? 'The Executive Layer backend is not running. Start it with: node backend/dev.js'
        : res.error);
      renderADTPage();return;
    }
    const d=res.data||{};
    if(d.status==='baseline'){
      showAiToast('Watching from here','Bhaiyaa has '+d.cursor+' stores already. Sign-ups from now on will appear on this board.');
    }else if(d.count){
      showAiToast(d.count+' new store'+(d.count===1?'':'s'),
        (d.stores||[]).map(function(s){return s.store_name;}).join(', ')+' — waiting on KYC.');
    }else{
      showAiToast('Nothing new','No sign-ups on Bhaiyaa since the last check.');
    }
    soLoadLiveRuns().then(function(){renderADTPage();});
  });
}
/* The headline counts store openings, not stores: six of these twelve have no store in either
   system yet, and calling them stores would name something that does not exist.

   The second clause counts what has STOPPED, and deliberately does not say "needs you" — one of
   the two halts is a UIDAI mismatch, which the journey hands to Compliance, not to this role.
   A header that claims work is yours when it is not is how a queue stops being trusted.

   The action is the real store intake journey (startStoreIntake), which is stage 1 of this same
   rail — so the page can both watch the journey and start one. */
function buildSoHeaderHTML(){
  const p=getActivePersona();
  const stuck=soRunsAll().filter(soIsHalted).length;
  const sub='You are looking after '+soRunsAll().length+' store opening'+(soRunsAll().length===1?'':'s')+'.'
    +(stuck?' <b>'+stuck+'</b> ha'+(stuck===1?'s':'ve')+' stopped.':' Nothing has stopped.');
  return '<div class="am-head">'
    +'<div class="am-head-left">'
      +'<div class="am-head-title">'+p.name+' <span class="am-head-role">'+p.label+'</span></div>'
      +'<div class="am-head-sub">'+sub+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:10px;align-items:center">'
    +'<button class="am-head-new" style="background:#fff;color:#0f172a;border:1px solid #cbd5e1"'
      +' onclick="soSyncFromBhaiyaa()"'+(soSyncing?' disabled':'')+'>'
      +(soSyncing
        ?'<span class="uif-spin" style="margin-right:2px"></span>Syncing&hellip;'
        :'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M21 2v6h-6"/><path d="M3 12a9 9 0 0 1 15-6.7L21 8"/><path d="M3 22v-6h6"/><path d="M21 12a9 9 0 0 1-15 6.7L3 16"/></svg>Sync from Bhaiyaa')
      +'</button>'
    +'<button class="am-head-new" onclick="startStoreIntake()">'
      +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>'
      +'New store</button>'
    +'</div>'
    +'</div>';
}
/* Five segments instead of nine, so they are wide enough to carry the full stage name with no
   truncation — which is why this rail has no separate `short`/`label` split to reconcile. */
function soSegmentHTML(s){
  const count=soStageCount(s.id);
  const selected=soPipelineStage===s.id;
  const flag=s.gate?' · nothing exists until this clears':s.merchantAction?' · waiting on the merchant':'';
  return '<button type="button" class="am-seg tone-'+s.tone+(selected?' selected':'')+(count?'':' empty')+'"'
    +' onclick="soSelectPipelineStage(\''+s.id+'\')"'
    +' title="'+attrSafe(stripEnt(s.label)+flag+' — '+stripEnt(s.internal))+'">'
    +'<span class="am-seg-bar"></span>'
    +'<span class="am-seg-top"><span class="am-seg-count">'+count+'</span></span>'
    +'<span class="am-seg-label">'+s.short+'</span>'
    +'</button>';
}
function soTrackGroupHTML(track){
  const stages=soPipelineStages.filter(function(s){return s.track===track.id;});
  return '<div class="am-bar-group" style="flex:'+stages.length+'"'
    +' title="'+attrSafe(track.label+' — '+stripEnt(track.plain))+'">'
    +stages.map(soSegmentHTML).join('')+'</div>';
}
function buildSoPipelineHTML(){
  return '<div class="am-bar-card">'
    +'<div class="am-bar">'+soTrackGroupHTML(soPipelineTracks[0])+'<span class="am-bar-div"></span>'+soTrackGroupHTML(soPipelineTracks[1])+'</div>'
    +'</div>';
}
function soSelectPipelineStage(id){
  soPipelineStage=soPipelineStage===id?'':id;
  soSelectedId=null;soPage=1;
  renderADTPage();
}
function soClearPipelineStage(){
  soPipelineStage='';soSelectedId=null;soPage=1;
  renderADTPage();
}
function soGoToPage(n){
  soPage=Math.max(1,n);soSelectedId=null;
  renderADTPage();
}
function soListPaginationHTML(total,totalPages,start){
  const prev='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg>';
  const next='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg>';
  const buttons=Array.from({length:totalPages},function(_,i){
    return '<button class="lp-pg-btn'+(soPage===i+1?' active':'')+'" onclick="soGoToPage('+(i+1)+')">'+(i+1)+'</button>';
  }).join('');
  return '<div class="lp-pagination">'
    +'<span class="lp-pagination-info">Showing '+(total===0?0:start+1)+'&ndash;'+Math.min(start+SO_PAGE_SIZE,total)+' of '+total+' entries</span>'
    +'<div class="lp-pagination-controls">'
    +'<button class="lp-pg-btn lp-pg-arrow" onclick="soGoToPage('+(soPage-1)+')"'+(soPage===1?' disabled':'')+'>'+prev+'</button>'
    +buttons
    +'<button class="lp-pg-btn lp-pg-arrow" onclick="soGoToPage('+(soPage+1)+')"'+(soPage===totalPages?' disabled':'')+'>'+next+'</button>'
    +'</div></div>';
}
function soBadgeClass(stageId){
  const s=soStageById(stageId);if(!s)return 'pending';
  if(s.tone==='green')return 'approved';
  if(s.tone==='red')return 'inactive';
  if(s.tone==='amber')return 'pending';
  return 'expired';
}
function soRoleLabel(d){return d.role==='buyer'?'Buyer':'Seller';}
/* Where it is now: the stage, the one step in progress, and how far into the stage that is.
   A halted run says so here rather than only in the drawer — it is the difference between a
   record that is moving slowly and one that has stopped, and the listing is where that gets
   triaged. */
function soWhereCellHTML(d){
  const s=soStageById(d.stage)||{};
  const steps=soSteps(d,d.stage);
  if(!steps.length)return '<span class="lp-dash">&mdash;</span>';
  const idx=soSubIndex(d);
  const cur=steps[idx];
  return '<div class="am-where" title="'+attrSafe(stripEnt(s.plain))+'">'
    +'<span class="am-sub-pill '+soBadgeClass(d.stage)+'">'+s.short+'</span>'
    +'<span class="am-where-step">'+cur.label
      +(cur.auto?'<span class="am-sub-tag auto">'+amBoltSvg+' auto</span>':'')
      +(soIsHalted(d)?'<span class="am-sub-tag breach">halted</span>':'')+'</span>'
    +'<span class="am-where-prog">Step '+(idx+1)+' of '+steps.length+'</span>'
    +'</div>';
}
function soNextActionCellHTML(d){
  const a=soNextAction(d);
  // A synced store waiting on KYC is the one automated step somebody actually performs here, so
  // the column offers it rather than saying "Auto" beside a row nothing is going to move. It
  // opens the drawer, because that is where the check runs — the listing never has the Aadhaar.
  if(d.live&&d.stage==='kyc')return '<button class="am-act do" onclick="event.stopPropagation();openSoRunSidebar('+d.id+');navSoRunTab(\'logs\')">'
    +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M9 12l2 2 4-4"/><circle cx="12" cy="12" r="9"/></svg> Run KYC</button>';
  if(a.kind==='auto')return '<span class="am-act auto">'+amBoltSvg+' Auto</span>';
  if(a.kind==='do')return '<button class="am-act do" onclick="event.stopPropagation();soCompleteStep('+d.id+')">'
    +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2"><polyline points="20 6 9 17 4 12"/></svg> '+a.label+'</button>';
  if(a.kind==='chase')return '<button class="am-act chase" onclick="event.stopPropagation();soRemindMerchant('+d.id+')">'
    +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M4 4h16v12H7l-3 3z"/></svg> '+a.label+'</button>';
  return '<span class="am-act wait">'+a.label+'</span>';
}
/* == THE KYC HAND-OFF ====================================================================
   What Bhaiyaa returned for this store, shown in the drawer before you leave for the journey.
   It is a preview rather than the whole record on purpose: enough to recognise which merchant
   this is and that there is something real to check, not enough to make the trip pointless. == */
function soKycPreviewHTML(d){
  const sg=soSignupFor(d);
  if(!sg)return '';
  const row=function(k,v){
    return '<div class="so-kycp-row"><span class="so-kycp-k">'+k+'</span>'
      +'<span class="so-kycp-v">'+attrSafe(v)+'</span></div>';
  };
  return '<div class="so-kycp">'
    +'<div class="so-kycp-head">'
      +'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M21 12a9 9 0 1 1-6.2-8.6"/><polyline points="21 3 21 9 15 9"/></svg>'
      +'Fetched from seller.bhaiyaa</div>'
    +row('Owner',sg.owner)
    +row('Aadhaar',bhaiyaaMaskAadhaar(sg.aadhaar))
    +row('PAN',sg.pan)
    +row('Entity',sg.entity)
    +'</div>';
}
/* Leaves the board for the journey, remembering which record to come back to. storeIntakeDraft
   is loaded from what Bhaiyaa returned, because the KYC screen was written to read a draft and
   a verification of an existing store is the same screen reading a different source. */
function soOpenKycVerification(runId){
  const d=soRuns.find(function(x){return x.id===runId;});if(!d)return;
  const sg=soSignupFor(d)||{};
  soKycRunId=runId;
  soKycVerified=false;
  // The board is a dashboard tab, not a page of its own — so Exit lands on 'dashboard' and the
  // tab is restored separately on the way back. Sending it to 'store-ops' would 404 the router.
  storeIntakeBackPage='dashboard';
  storeIntakeDraft={
    first_name:(sg.owner||d.merchant||'').split(' ')[0]||'',
    last_name:(sg.owner||d.merchant||'').split(' ').slice(1).join(' '),
    email_id:sg.email||'',mobile_number:(sg.mobile||'').replace(/^\+\d+\s*/,''),
    aadhaar_number:sg.aadhaar||'',pan_number:sg.pan||'',gst_number:sg.gst||'',
    business_kyc:sg.entity||'',store_name:d.store,store_category:d.category,store_type:d.band
  };
  storeIntakeResult=null;storeIntakeBusy=false;
  storeIntakeStep=1;storeReviewStage=-1;
  storeKycProgress=-1;storeKycDone=false;
  navigatePage('create-store');
  storeRunKyc();
}
// Back to the board with the drawer open on the record you left from, on its Logs tab — the
// same place the trip started, so a verification reads as a round trip rather than a redirect.
function soKycReturnToBoard(){
  const id=soKycRunId;
  soKycRunId=null;soKycVerified=false;
  storeIntakeStep=0;storeIntakeDraft={};
  // Selection set before the render, not after: openSoRunSidebar patches a drawer into a DOM
  // that does not exist yet at this point, so the state has to be right when the page draws.
  if(id){soSelectedId=id;soRunTab='logs';}
  dashboardTab='store-ops';
  navigatePage('dashboard');
}
/* Four columns and the row opener. One fewer than the deal board, because a store opening has
   no second party to name: the merchant IS the customer, so "who this is for" and "who we are
   waiting on" collapse into one cell. Store ID, Bhaiyaa ref, plan, GST and business tier are
   all things you look up about one record, so they live in the drawer.

   WHAT TO DO NEXT IS GONE, and its removal is the point rather than a saving. Acting on a run
   now means opening it — reading the evidence, then deciding — and a one-click button in a row
   is the opposite of that: it completes a step for a record whose details you have not looked
   at. The action still exists, unchanged, at the top of the drawer's Logs tab, which is the one
   place that shows you what you are agreeing to before you agree to it. The drawer is the single
   action surface now; the listing is for finding the row you want. */
function buildSoListingHTML(){
  const hamburger='<svg width="16" height="14" viewBox="0 0 18 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="1" y1="2" x2="17" y2="2"/><line x1="1" y1="7" x2="17" y2="7"/><line x1="1" y1="12" x2="17" y2="12"/></svg>';
  const stage=soPipelineStage?soStageById(soPipelineStage):null;
  const all=soRunsForStage(soPipelineStage);
  const total=all.length;
  const totalPages=Math.max(1,Math.ceil(total/SO_PAGE_SIZE));
  if(soPage>totalPages)soPage=totalPages;
  if(soPage<1)soPage=1;
  const start=(soPage-1)*SO_PAGE_SIZE;
  const rows=all.slice(start,start+SO_PAGE_SIZE);
  if(soSelectedId&&!rows.some(function(d){return d.id===soSelectedId;}))soSelectedId=null;
  const title=stage?stage.short:'Every store opening';
  const sub=stage?stripEnt(stage.plain)+' &nbsp;·&nbsp; Should take: '+(soStageSla[stage.id]||'&mdash;')
    :'Everything you own, in one list. Click a step above to narrow it down.';
  const compact=!!soSelectedId;
  // The widths sum to 100 in both states — see the deal board's colgroup note for why that is
  // generated from one list rather than written twice. The 18% the action column used to hold
  // goes to Store and Where it is now, which are what you scan by.
  const columns=[
    // A synced store names Bhaiyaa's own id beside ours. Two reasons: it is how an operator
    // lines this row up with the record on Bhaiyaa, and it is what tells them at a glance which
    // rows are real — the seeded twelve survive a refresh only because they are fiction.
    {w:'31%',cw:'40%',th:'Store',
     cell:function(d){return '<div class="cell-primary am-c-client">'+d.store+'</div>'
       +'<div class="cell-sub">'+d.ref+(d.live?' &middot; Bhaiyaa '+d.bhaiyaaRef:'')+'</div>';}},
    {w:'24%',hideWhenCompact:true,th:'Merchant',
     cell:function(d){return '<div class="cell-primary am-c-client">'+d.merchant+'</div><div class="cell-sub">'+soRoleLabel(d)+' &middot; '+d.category+'</div>';}},
    {w:'29%',cw:'44%',th:'Where it is now',cell:soWhereCellHTML},
    {w:'8%',hideWhenCompact:true,th:'Days',thTitle:'Days sitting on the current step',
     cell:function(d){return '<span class="am-c-age'+(d.breach?' breach':'')+'">'+d.age+'d</span>'
       +(d.breach?'<div class="cell-sub am-c-late">Too long</div>':'');}},
    {w:'8%',cw:'16%',th:'',
     cell:function(d){return '<button class="lp-action-btn" onclick="event.stopPropagation();openSoRunSidebar('+d.id+')" title="Open this record">'+hamburger+'</button>';}}
  ].filter(function(c){return !(compact&&c.hideWhenCompact);});
  const colgroup='<colgroup>'+columns.map(function(c){return '<col style="width:'+(compact?c.cw:c.w)+'">';}).join('')+'</colgroup>';
  const head='<thead><tr>'+columns.map(function(c){return '<th'+(c.thTitle?' title="'+attrSafe(c.thTitle)+'"':'')+'>'+c.th+'</th>';}).join('')+'</tr></thead>';
  const body=rows.length?rows.map(function(d){
    return '<tr class="am-row'+(soSelectedId===d.id?' lp-row-selected':'')+'" id="so-row-'+d.id+'" style="cursor:pointer" onclick="openSoRunSidebar('+d.id+')">'
      +columns.map(function(c){return '<td>'+c.cell(d)+'</td>';}).join('')
      +'</tr>';
  }).join('')
    :'<tr><td colspan="'+columns.length+'" style="padding:34px;text-align:center;color:var(--gray);font-size:12.5px">Nothing here right now.</td></tr>';
  return '<div class="am-list-block">'
    +'<div class="am-list-head">'
      +'<div><div class="am-list-title">'+title+'</div><div class="am-list-sub">'+sub+'</div></div>'
      +'<div class="am-list-right"><span class="am-list-count">'+total+' of '+soRunsAll().length+'</span>'
      +(stage?'<button class="lp-pill-reset" onclick="soClearPipelineStage()">Show all</button>':'')+'</div>'
    +'</div>'
    +'<div class="lp-split-wrap"><div class="lp-split-main">'
    +'<table class="lp-table am-table">'+colgroup+head+'<tbody>'+body+'</tbody></table>'
    +soListPaginationHTML(total,totalPages,start)
    +'</div>'
    +'<div class="lp-split-sb'+(soSelectedId?' open':'')+'" id="so-split-sb"><div class="lp-isb" id="so-isb-inner">'+(soSelectedId?renderSoRunSidebar():'')+'</div></div>'
    +'</div></div>';
}
function soStampToday(d){
  const now=new Date();
  d.updated=now.getDate()+' '+amMonths[now.getMonth()]+' '+now.getFullYear();
  d.age=0;
}
/* == MOVING A RUN FORWARD ================================================================
   The only writer. Finish the step the record is sitting on; if it was the last step of the
   stage, the record moves to the next stage — the stage is always a consequence of the steps
   underneath it and is never set directly.

   Clearing a halt step is the same operation, plus dropping the halt: a mismatch that has been
   reviewed or a registration that has been retried is no longer a stopped run, and leaving the
   flag on would keep offering the same button forever. */
/* `quiet` suppresses the toast and the re-render, and exists for one caller: soKycMakeLive walks
   several steps in a row, and a board that repaints four times and stacks four toasts to report
   one action is reporting the implementation rather than the action. The writing is unchanged —
   what is suppressed is only the announcement, which that caller makes once at the end. */
function soAdvanceStep(runId,simulated,quiet){
  // soRunsAll(), not soRuns: a store synced from Bhaiyaa lives in soLiveRuns, and advancing one
  // is exactly what the KYC hand-off does — looking in the seeded list only would silently
  // return on every real record.
  const d=soRunsAll().find(function(x){return x.id===runId;});if(!d)return;
  const steps=soSteps(d,d.stage);
  const idx=soSubIndex(d);
  const cur=steps[idx];if(!cur)return;
  if(!simulated&&!amCanAdvance(cur.owner)){showAiToast('Not yours to complete','&ldquo;'+cur.label+'&rdquo; belongs to '+cur.owner+'.');return;}
  const who=amOwnerInfo(cur.owner).who;
  const commentEl=document.getElementById('so-log-comment');
  const comment=commentEl?commentEl.value.trim():'';
  if(!simulated&&commentEl&&!comment){showAiToast('A comment is required','Add a note for this action before marking it done.');commentEl.focus();return;}
  const wasHalt=!!cur.halt;
  // Where this step happened, captured before anything moves — the notes written at the end of
  // this function belong to it, not to wherever the record ends up.
  const at={stage:soStageById(d.stage),subNo:idx+1};
  d.breach=false;soStampToday(d);
  if(wasHalt){d.halted='';d.haltNote='';}
  // Recomputed after the halt is dropped: clearing it removes the step from this stage, so the
  // stage's last index is not what it was one line ago.
  const liveSteps=soSteps(d,d.stage);
  const wasLast=idx>=liveSteps.length-1;
  const stageBefore=d.stage;
  if(!wasLast){d.sub=idx+1;}
  else{
    const nextStage=soPipelineStages[soStageIndex(d.stage)+1];
    if(nextStage){d.stage=nextStage.id;d.sub=0;}
  }
  const autoRan=soSkipAutoSteps(d);
  if(comment)soPushNote(d,'Note on &ldquo;'+cur.label+'&rdquo;',comment,at);
  // A cleared halt is worth a line of its own: the step it belonged to is gone from the derived
  // trail the moment the flag drops, so without this the record would carry no evidence it ever
  // stopped — which is the one thing anyone reviewing it afterwards wants to know.
  if(wasHalt)soPushNote(d,cur.label+' cleared','The run was halted here and has been released by '+actorLabel(currentActorId())+'.',at);
  const landed=soCurrentSub(d);
  const autoMsg=autoRan.length?' Automation ran: '+autoRan.join(', ')+'.':'';
  if(quiet)return;
  if(d.stage!==stageBefore){
    const st=soStageById(d.stage);
    showAiToast('Moved to &ldquo;'+st.short+'&rdquo;',d.ref+' &middot; '+d.store+' is now at &ldquo;'+stripEnt(st.label)+'&rdquo;.'+autoMsg);
  }else if(landed&&landed!==cur){
    showAiToast(simulated?'Simulated &mdash; '+cur.label:cur.label+' &mdash; done',
      (simulated?who+' completed this. ':'')+d.ref+' &middot; next up: '+landed.label+'.'+autoMsg);
  }else{
    showAiToast('All done',d.store+' is open on Bhaiyaa.'+autoMsg);
  }
  renderADTPage();
}
/* == THE OWNER CHECK, FOR A REAL STORE ===================================================
   The same four checks the New store journey runs (bhaiyaaKycChecks), on the same rail markup,
   against a store that arrived from Bhaiyaa instead of one being typed in. Reusing the list
   rather than copying it is the point: two KYC screens that drift apart would let a reviewer
   see one thing here and another there.

   It is a demonstration, and the panel says so. Bhaiyaa's signup captures an Aadhaar document
   and never a number, so there is nothing to send to UIDAI even if we were sending anything —
   the Ops Manager types the number, and the checks are theatre over it. Labelling that plainly
   is not modesty: an Ops Manager who believes a government identity check happened, when
   nothing left the building, is the worst outcome this screen can produce. == */
let soKycProgress=-1,soKycBusy=false;
function soLiveKycPanelHTML(d){
  const running=soKycBusy||soKycProgress>=0;
  const evidence=soKycEvidence(d);
  return '<div class="lp-logs-form">'
    +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:#ef4444;display:inline-block;flex-shrink:0"></span>Next: Verify the owner</div>'
    +'<p class="lp-logs-form-sub">The KYC agent checks this Aadhaar with UIDAI and matches it against the name on the signup. '
      +'Bhaiyaa will not open a store without it &mdash; so this runs before anything is created, not after.</p>'
    +(running
      ?'<div id="so-kyc-list" class="uif-proc">'+soKycListHTML(evidence)+'</div>'
      :'<div class="lp-logs-form-label">Aadhaar Number</div>'
        +'<input id="so-kyc-aadhaar" class="lp-logs-form-textarea" style="min-height:0;height:38px" '
        +'placeholder="0000 0000 0000" maxlength="14" autocomplete="off">'
        +'<div class="lp-logs-form-label">Comment</div>'
        +'<textarea id="so-log-comment" class="lp-logs-form-textarea" placeholder="Add a note for this action..."></textarea>'
        +'<button class="lp-logs-save-btn" onclick="soRunLiveKyc('+d.id+')">Run the owner check</button>')
    +'</div>';
}
// What each check compared. "Name match ✓" alone is a claim; "Ravi Sharma ≈ RAVI SHARMA ✓" is
// evidence — the same reasoning as the intake journey's panel.
function soKycEvidence(d){
  const owner=d.merchant&&d.merchant!=='—'?d.merchant:d.store;
  return {
    format:soKycMasked,
    uidai:'Demographics returned by UIDAI',
    name:owner+' ≈ '+String(owner).toUpperCase(),
    screen:'0 matches on sanctions or watchlists'
  };
}
let soKycMasked='XXXX XXXX XXXX';
function soKycListHTML(evidence){
  return bhaiyaaKycChecks.map(function(c,i){
    const state=soKycProgress>i?'is-done':(soKycProgress===i?'is-active':'');
    const mark=soKycProgress>i
      ? '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3.5"><polyline points="20 6 9 17 4 12"/></svg>'
      : (soKycProgress===i?'<span class="uif-spin"></span>':'');
    return '<div class="uif-proc-item st-run-item '+state+'">'
      +'<div class="uif-proc-rail"><div class="uif-proc-dot">'+mark+'</div>'
      +(i<bhaiyaaKycChecks.length-1?'<div class="uif-proc-line"></div>':'')+'</div>'
      // Same markup as the New store journey's panel (storeKycListHTML) on purpose — one KYC
      // screen in this product, rendered in two places, not two screens that drift.
      +'<div class="uif-proc-body"><div class="uif-proc-title">'+c.label+'</div>'
      +(soKycProgress>i?'<div class="uif-proc-note">'+c.done+'</div>'
        +'<div class="st-io st-io--write"><span class="st-io-tag">Checked</span><div class="st-io-list">'
        +'<span class="st-io-pair"><span class="st-io-v">'+attrSafe(evidence[c.id])+'</span></span></div></div>'
        :(soKycProgress===i?'<div class="uif-proc-note">'+c.running+'</div>':''))
      +'</div></div>';
  }).join('');
}
/* Runs the checks, then writes the result. The animation is paced so it can be read; the write
   happens once it finishes, and the run only moves after the backend has agreed — a badge that
   flips before the record does is how the two end up disagreeing. */
function soRunLiveKyc(runId){
  const d=soRunsAll().find(function(x){return x.id===runId;});if(!d||soKycBusy)return;
  const input=document.getElementById('so-kyc-aadhaar');
  const digits=String(input?input.value:'').replace(/\D/g,'');
  if(digits.length!==12){
    showAiToast('Aadhaar number needed','Enter the 12 digits from the owner’s Aadhaar to run the check.');
    if(input)input.focus();
    return;
  }
  soKycMasked=bhaiyaaMaskAadhaar(digits);
  const note=(document.getElementById('so-log-comment')||{}).value||'';
  soKycBusy=true;soKycProgress=0;
  renderADTPage();
  const evidence=soKycEvidence(d);
  const advance=function(i){
    soKycProgress=i;
    const el=document.getElementById('so-kyc-list');
    if(el)el.innerHTML=soKycListHTML(evidence);
    if(i>=bhaiyaaKycChecks.length){setTimeout(function(){soFinishLiveKyc(d,note);},520);return;}
    setTimeout(function(){advance(i+1);},720);
  };
  setTimeout(function(){advance(1);},720);
}
function soFinishLiveKyc(d,note){
  execApiRequest('POST','/stores/'+encodeURIComponent(d.code)+'/kyc',
    {user:getActivePersona().name,aadhaar_masked:soKycMasked,comment:note}).then(function(res){
    soKycBusy=false;soKycProgress=-1;
    if(!res.ok){
      // The checks "passed" on screen and the record did not move. Say so rather than leaving a
      // green rail above a store that is still Pending.
      showAiToast('KYC not saved',(res.offline?'The backend is not running.':res.error)
        +' The store is still waiting on KYC.');
      renderADTPage();return;
    }
    soPushNote(d,'KYC verified','Owner checked against UIDAI and screened. Aadhaar '+soKycMasked+'.'
      +(note?' '+note:''),{stage:soStageById('kyc'),subNo:1});
    showAiToast('KYC verified',d.store+' &middot; the owner checks out. The store is open on Bhaiyaa.');
    // Reload rather than mutate: the backend decided what the store now is, and the board should
    // show that rather than our optimistic guess at it.
    soLoadLiveRuns().then(function(){renderADTPage();});
  });
}
function soCompleteStep(runId){soAdvanceStep(runId,false);}
// The merchant and the two agents are the parties this portal cannot act as. Simulating them is
// how a demo walks all five stages without a merchant on the other end of a signup link.
function soSimulateStep(runId){soAdvanceStep(runId,true);}
/* The real action on a merchant-owned step. It moves nothing — it records that we chased, which
   is the evidence an Ops Manager needs when a signup has sat for a week. */
function soRemindMerchant(runId){
  const d=soRunsAll().find(function(x){return x.id===runId;});if(!d)return;
  const cur=soCurrentSub(d)||{};
  const stage=soStageById(d.stage)||{};
  const now=new Date();const h=now.getHours();
  (soExtraLog[d.id]=soExtraLog[d.id]||[]).unshift({
    stage:stage,stageNo:stage.n,subNo:soSubIndex(d)+1,
    sub:{label:'Reminder sent to merchant'},
    owner:amOwnerInfo('Ops Manager'),ownerRole:'Ops Manager',
    state:'note',reminder:true,
    date:now.getDate()+' '+amMonths[now.getMonth()]+' '+now.getFullYear(),
    time:(h%12||12)+':'+String(now.getMinutes()).padStart(2,'0')+' '+(h>=12?'PM':'AM'),
    note:'Chased &ldquo;'+cur.label+'&rdquo;.'
  });
  showAiToast('Reminder sent',d.merchant+' &middot; chased &ldquo;'+cur.label+'&rdquo;.');
  renderADTPage();
}
function openSoRunSidebar(id){
  soSelectedId=id;soRunTab='basic-details';
  const sb=document.getElementById('so-split-sb');if(sb)sb.classList.add('open');
  const inner=document.getElementById('so-isb-inner');if(inner)inner.innerHTML=renderSoRunSidebar();
  document.querySelectorAll('.am-row').forEach(function(r){r.classList.toggle('lp-row-selected',r.id==='so-row-'+id);});
}
function closeSoRunSidebar(){
  soSelectedId=null;
  const sb=document.getElementById('so-split-sb');if(sb)sb.classList.remove('open');
  document.querySelectorAll('.am-row').forEach(function(r){r.classList.remove('lp-row-selected');});
}
function navSoRunTab(tab){
  soRunTab=tab;
  const inner=document.getElementById('so-isb-inner');if(inner)inner.innerHTML=renderSoRunSidebar();
}
/* == THE RECORD DRAWER ===================================================================
   Three tabs, not the deal board's four. Details (the facts), Logs (where you act, and the
   trail of every step event), Workflow (the five stages, read-only). The fourth tab over there
   is a client mirror, and this journey needs none: the merchant sees Bhaiyaa's own signup,
   which is stages 1 and 2 themselves, not a translation of them. == */
function renderSoRunSidebar(){
  const d=soRunsAll().find(function(x){return x.id===soSelectedId;});if(!d)return '';
  const s=soStageById(d.stage)||{};
  const tabs=[{id:'basic-details',label:'Details'},{id:'logs',label:'Logs'},{id:'workflow',label:'Workflow'}];
  const tabBar='<div class="lp-isb-tabbar">'
    +'<div class="lp-isb-tabs">'+tabs.map(function(t){return '<button class="lp-isb-tab'+(soRunTab===t.id?' active':'')+'" onclick="navSoRunTab(\''+t.id+'\')">'+t.label+'</button>';}).join('')+'</div>'
    +'<div class="lp-isb-right"><button class="lp-isb-close" onclick="closeSoRunSidebar()" title="Close"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>'
    +'</div>';
  const iId='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 3H8a2 2 0 0 0-2 2v2h12V5a2 2 0 0 0-2-2z"/></svg>';
  const iUser='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
  const iShop='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 9.5 4.8 4h14.4L21 9.5"/><path d="M3 9.5h18a3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-6 0z"/><path d="M5 11.8V20h14v-8.2"/></svg>';
  const iMoney='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>';
  const iClock='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
  const iTag='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>';
  const fc=function(ico,label,val){return '<div class="lp-sb-field-card"><div class="lp-sb-field-icon">'+ico+'</div><div class="lp-sb-field-content"><div class="lp-sb-field-label">'+label+'</div><div class="lp-sb-field-value">'+val+'</div></div></div>';};
  // The halt is the first thing on every tab of a stopped record. Anything else answers a
  // question the reader does not have yet.
  const haltBox=soIsHalted(d)
    ?'<div class="so-halt"><b>This run has stopped.</b> '+d.haltNote+'</div>'
    :'';
  let body='';

  if(soRunTab==='basic-details'){
    // Plan and GST are derived from the turnover band by the same table the journey's Store
    // Creation step uses, so this drawer and that run can never quote different figures.
    const band=bhaiyaaBandFor(d.band);
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">'+d.store+'</span>'
      +'<span class="lp-status-badge '+soBadgeClass(d.stage)+'">'+s.short+'</span></div>'
      +'<div class="am-sb-plain">'+s.plain+'</div>'
      +haltBox
      +'<div class="lp-sb-detail-grid">'
      +fc(iId,'Store ID',d.ref)
      +fc(iId,'Bhaiyaa ref',d.bhaiyaaRef||'<span style="color:var(--gray)">Not issued yet</span>')
      +fc(iUser,'Merchant',d.merchant)
      +fc(iShop,'What this store does',d.role==='buyer'?'Buys from sellers':'Sells to customers')
      +fc(iTag,'Category',d.category)
      +fc(iShop,'Where',d.city)
      +fc(iMoney,'Business tier',d.band)
      +fc(iMoney,'Plan &amp; GST','<span style="color:var(--orange)">'+band.plan+'</span> &middot; '+band.gst)
      +fc(iClock,'Last touched',d.updated)
      +fc(iClock,'Days on this step',d.age+' day'+(d.age===1?'':'s'))
      +'</div>';

  }else if(soRunTab==='logs'){
    /* The action lives here, above the trail it writes into — one step, one button, the same
       next action the listing shows, so the two can never disagree. This is the only surface in
       the board that moves a run forward. */
    const a=soNextAction(d);
    const steps=soSteps(d,d.stage);
    const idx=soSubIndex(d);
    const own=amOwnerInfo(a.owner);
    const mine=a.kind==='do';
    const isAuto=a.kind==='auto';
    const simLabel=a.step&&a.step.decision?'Simulate: '+own.who+' chooses':'Simulate: '+own.who+' completes this';
    /* == THE HAND-OFF TO THE JOURNEY =====================================================
       A step flagged `opensKyc` is not completed from this panel. It is a verification, and a
       verification you can tick from a drawer without reading the evidence is a rubber stamp
       with a comment box — so the button leaves, carrying the record id, and lands on the
       journey's own KYC screen where the details Bhaiyaa returned are on screen and the four
       checks run in front of you. You come back having seen what you approved.

       This is also the only place the two surfaces meet: the board watches the journey, and
       this is the door between them. == */
    const opensKyc=a.step&&a.step.opensKyc&&!isAuto;
    // A store that really came from Bhaiyaa gets the owner check itself here rather than the
    // generic "runs automatically" card. It is the one step on this board an Ops Manager
    // performs against a live record, and the panel that shows it already exists — the same one
    // the New store journey runs, so a reviewer sees one KYC screen in this product, not two.
    const actionPanel=(d.live&&d.stage==='kyc')
      ?soLiveKycPanelHTML(d)
      :isAuto
      ?'<div class="lp-logs-form">'
        +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:var(--navy);display:inline-block;flex-shrink:0"></span>Runs automatically</div>'
        +'<p class="lp-logs-form-sub">&ldquo;'+a.step.label+'&rdquo; is performed by the AI Execution Layer'+(a.step.autoNote?' &mdash; '+a.step.autoNote:'')+'. Nothing to do here.</p>'
        +'</div>'
      :opensKyc
      ?'<div class="lp-logs-form">'
        +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:#f59e0b;display:inline-block;flex-shrink:0"></span>Next: '+a.step.label+'</div>'
        +'<p class="lp-logs-form-sub">The KYC agent has gathered everything seller.bhaiyaa holds on this owner. '
          +'Open the verification step to see the details it pulled and run the checks against them.'
          +' Step '+(idx+1)+' of '+steps.length+' in &ldquo;'+s.short+'&rdquo;'
          +(a.step.sla?' &middot; should take '+a.step.sla:'')+'.</p>'
        +soKycPreviewHTML(d)
        +'<button class="lp-logs-save-btn" onclick="soOpenKycVerification('+d.id+')">'
          +'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" style="vertical-align:-2px;margin-right:6px"><path d="M9 18l6-6-6-6"/></svg>'
          +(a.step.act||'Verify KYC')+'</button>'
        +'<div class="lp-logs-form-sub" style="margin:9px 0 0;text-align:center">Opens the KYC step of the Store Creation journey.</div>'
        +'</div>'
      :'<div class="lp-logs-form">'
        +'<div class="lp-logs-form-header"><span style="width:9px;height:9px;border-radius:50%;background:#f59e0b;display:inline-block;flex-shrink:0"></span>Next: '+a.step.label+'</div>'
        +'<p class="lp-logs-form-sub">'
          +(mine?(a.step.halt?'This run halted here. Clearing it releases the journey.':'This step is yours to complete.')
            :a.kind==='chase'?'Waiting on the merchant. You cannot fill their signup in for them.'
            :'Owned by '+own.who+' ('+a.owner+').')
          +' Step '+(idx+1)+' of '+steps.length+' in &ldquo;'+s.short+'&rdquo;'
          +(a.step.sla?' &middot; should take '+a.step.sla:'')+'.</p>'
        +'<div class="lp-logs-form-label">Comment'+(mine?' <span class="lp-logs-form-req">*</span>':'')+'</div>'
        +'<textarea id="so-log-comment" class="lp-logs-form-textarea" placeholder="Add a note for this action..."></textarea>'
        +(mine
          ?'<button class="lp-logs-save-btn" onclick="soCompleteStep('+d.id+')">'+(a.step.act||'Mark &ldquo;'+a.step.label+'&rdquo; done')+'</button>'
          :'<button class="lp-logs-save-btn" onclick="soSimulateStep('+d.id+')">'+simLabel+'</button>'
            +(a.kind==='chase'?'<button class="am-sb-chase-link" onclick="soRemindMerchant('+d.id+')">Send the merchant a reminder instead</button>':''))
        +'</div>';
    const log=soRunLog(d);
    const personSvg='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
    const calSvg='<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
    const clkSvg='<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
    const timeline=log.length?log.map(function(e,i){
      const sk=e.state==='current'||e.state==='note'?'default':'active';
      return '<div class="lp-log-row">'
        +'<div class="lp-log-avatar-col"><div class="lp-log-avatar lp-log-avatar--'+sk+'">'+personSvg+'</div>'+(i<log.length-1?'<div class="lp-log-connector"></div>':'')+'</div>'
        +'<div class="lp-log-card">'
        +'<div class="lp-log-status-row"><span class="lp-log-dot lp-log-dot--'+sk+'"></span>'
          +'<span class="lp-log-status-text lp-log-status-text--'+sk+'">'+e.sub.label+'</span>'
          +(e.sub.auto?'<span class="am-sub-tag auto">'+amBoltSvg+' auto</span>':'')
          +(e.reminder?'<span class="am-sub-tag loop">reminder</span>':'')
          +(e.state==='current'?'<span class="am-sub-tag loop">happening now</span>':'')
          +(e.state==='current'&&soIsHalted(d)?'<span class="am-sub-tag breach">halted</span>':'')
          +(e.breach?'<span class="am-sub-tag breach">took too long</span>':'')+'</div>'
        // Auto steps are credited to the layer that ran them, not to the role that answers for them.
        +'<div class="lp-log-meta-row"><span class="lp-log-meta-item">'+personSvg+'<span>'+(e.sub.auto?'AI Execution Layer':e.owner.who)+'</span></span>'
          +'<span class="lp-log-meta-item">'+calSvg+'<span>'+e.date+'</span></span>'
          +'<span class="lp-log-meta-item">'+clkSvg+'<span>'+e.time+'</span></span></div>'
        +'<div class="lp-log-comment-row"><span class="lp-log-comment-label">In:</span>'+e.stageNo+'. '+e.stage.short
          +' &middot; '+(e.note?e.note:e.state==='current'?'In progress.':'Finished.')+'</div>'
        +'</div></div>';
    }).join(''):'<div class="lp-logs-empty">Nothing has happened yet.</div>';
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">'+d.ref+' &middot; '+d.store+'</span>'
      +'<span class="am-int-chip">Internal</span></div>'
      +haltBox
      +'<div class="am-sb-loghead">Everything that has happened <span>'+log.length+' entr'+(log.length===1?'y':'ies')+', newest first</span></div>'
      +'<div class="lp-logs-wrap"><div class="lp-logs-timeline">'+timeline+'</div>'+actionPanel+'</div>';

  }else{
    /* Stage-level and read-only: the five steps of the journey, which are done, which one is
       live, and who finished each. To change anything you go to Logs — the same division the
       deal board draws, so a user who has read one record here can read any record anywhere. */
    const curIdx=soStageIndex(d.stage);
    const log=soRunLog(d);
    const rows=soPipelineStages.map(function(st,i){
      const state=i<curIdx?'done':i===curIdx?'current':'upcoming';
      const steps=soSteps(d,st.id);
      const doneCount=i<curIdx?steps.length:i===curIdx?soSubIndex(d)+1:0;
      const last=log.filter(function(e){return e.stage.id===st.id&&!e.reminder;})[0];
      const mark=state==='done'?'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2"><polyline points="20 6 9 17 4 12"/></svg>':String(st.n);
      const autoN=steps.filter(function(x){return x.auto;}).length;
      const cur=soCurrentSub(d)||{};
      return '<div class="am-cv-row '+state+'">'
        +'<div class="am-cv-markcol"><div class="am-cv-mark">'+mark+'</div>'+(i<soPipelineStages.length-1?'<div class="am-cv-line"></div>':'')+'</div>'
        +'<div class="am-cv-body"><div class="am-cv-label">'+st.short
          +(st.gate?'<span class="am-sub-tag breach">gate</span>':'')
          +(autoN?'<span class="am-sub-tag auto">'+amBoltSvg+' '+autoN+' of '+steps.length+' auto</span>':'')
          +'</div>'
        +'<div class="am-cv-sub">'
          +(state==='done'?doneCount+' of '+steps.length+' steps done'+(last?' &middot; last by '+last.owner.who+' on '+last.date:'')
            :state==='current'?'On step '+doneCount+' of '+steps.length+' &middot; '+cur.label
              +(cur.auto?' &middot; runs automatically':' &middot; waiting on '+(cur.owner||'&mdash;'))
            :'Not started &middot; '+steps.length+' step'+(steps.length===1?'':'s')+' &middot; '+st.waitingOn)
        +'</div></div></div>';
    }).join('');
    /* Automation that has already run, as facts rather than tasks — nobody will ever tick these,
       and the Logs tab should never offer to. Upcoming automation is left out on purpose: it
       would be a promise, not a record. */
    const autoRan=[];
    soPipelineStages.forEach(function(st,si){
      if(si>curIdx)return;
      const steps=soSteps(d,st.id);
      const upto=si<curIdx?steps.length:soSubIndex(d)+1;
      steps.slice(0,upto).forEach(function(sub){if(sub.auto)autoRan.push({stage:st,sub:sub});});
    });
    const autoSection=autoRan.length
      ?'<div class="am-sb-steps" style="margin-top:14px">'
        +'<div class="am-sb-steps-head">Run by the agents<span>'+autoRan.length+' action'+(autoRan.length===1?'':'s')+'</span></div>'
        +autoRan.map(function(x){
          return '<div class="am-auto-row">'
            +'<span class="am-auto-bolt">'+amBoltSvg+'</span>'
            +'<span class="am-auto-txt"><b>'+x.sub.label+'</b><i>'+(x.sub.autoNote||'automated')+' &middot; by '+x.sub.owner+' in &ldquo;'+x.stage.short+'&rdquo;</i></span>'
            +'<span class="am-auto-done">Done</span>'
            +'</div>';
        }).join('')
        +'</div>'
      :'';
    body='<div class="lp-sb-view-header"><span class="lp-sb-section-title">How far this has got</span>'
      +'<span class="am-int-chip">Internal</span></div>'
      +haltBox
      +'<div class="am-cv-intro">The five steps of the Bhaiyaa Store Creation Journey, and what has already been done on this one. To change anything, use the Logs tab.</div>'
      +'<div class="am-cv-list">'+rows+'</div>'
      +autoSection;
  }
  return tabBar+'<div class="lp-isb-body">'+body+'</div>';
}
