  const hasMyTasks=['entity-admin','entity-user'].indexOf(portalRole)>=0;
  const viewAll=hasMyTasks?'<span class="emp-act-viewall" onclick="navigatePage(\'my-tasks\')">View All</span>':'';
  return '<div class="dash-ref">'
