    +'</tr></thead><tbody>'+rows+'</tbody></table>'
    +'</div></div>'
    +'<div class="lp-split-sb'+(tmSelectedId?' open':'')+'" id="tm-split-sb"><div class="lp-isb" id="tm-isb-inner">'+sbInner+'</div></div>'
    +'</div></div>';
